          style={{
            flexDirection: 'row',
            alignItems: 'center',
            backgroundColor: isDark ? '#2e2c2e' : '#f1f0ec',
            borderRadius: 14,
            borderWidth: 1.5,
            borderColor: focusedInput === 'password' ? colors.primary : 'transparent',
            paddingHorizontal: 16,
            height: 54,
          }}
        >
          <Ionicons
            name="lock-closed-outline"
