              name={showPassword ? 'eye-off-outline' : 'eye-outline'}
              size={20}
              color={colors.inkGhost}
            />
          </Pressable>
        </View>
        {password.length > 0 && (
          <View style={{ flexDirection: 'row', gap: 6, marginTop: 8 }}>
            {[1, 2, 3, 4].map((level) => (
              <View
                key={level}
                style={{
                  flex: 1,
                  height: 3,
                  borderRadius: 2,
                  backgroundColor:
                    password.length >= level * 3
                      ? password.length >= 10
                        ? colors.success
                        : colors.warning
                      : isDark
                      ? '#3a383a'
                      : '#eceae6',
                }}
              />
            ))}
          </View>
        )}
      </View>

      {/* Confirm Password */}
      <View style={{ marginBottom: 28 }}>
        <Text
          style={{
            fontFamily: 'Inter_600SemiBold',
            fontSize: 12,
            color: colors.inkSoft,
            marginBottom: 8,
            letterSpacing: 0.6,
            textTransform: 'uppercase',
          }}
        >
          Confirm Password
        </Text>
        <View
          style={{
            flexDirection: 'row',
