          />
          <Pressable onPress={() => setShowConfirmPassword(!showConfirmPassword)} style={{ padding: 4 }}>
            <Ionicons
              name={showConfirmPassword ? 'eye-off-outline' : 'eye-outline'}
              size={20}
              color={colors.inkGhost}
            />
          </Pressable>
        </View>
        {confirmPassword.length > 0 && confirmPassword !== password && (
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 5, marginTop: 6 }}>
            <Ionicons name="alert-circle" size={13} color={colors.error} />
            <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 12, color: colors.error }}>
              Passwords don't match
            </Text>
          </View>
        )}
      </View>

      {/* Register Button */}
      <Pressable
        onPress={handleRegister}
        disabled={registerMutation.isPending}
        style={({ pressed }) => ({
          borderRadius: 14,
          height: 54,
          overflow: 'hidden',
          marginBottom: 16,
          shadowColor: colors.primary,
          shadowOffset: { width: 0, height: 8 },
          shadowOpacity: 0.42,
          shadowRadius: 16,
          elevation: 8,
          opacity: registerMutation.isPending ? 0.72 : 1,
          transform: [{ scale: pressed ? 0.978 : 1 }],
        })}
      >
        <LinearGradient
          colors={[colors.primary, colors.primary, colors.primaryDim] as [string, string, string]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}
        >
          <Text
            style={{
              fontFamily: 'Inter_700Bold',
              fontSize: 16,
              color: '#18181a',
              letterSpacing: 0.2,
            }}
          >
            {registerMutation.isPending
              ? 'Creating Account...'
              : accountType === 'vendor'
              ? 'Apply as Vendor'
              : 'Create Account'}
          </Text>
        </LinearGradient>
      </Pressable>

      {/* Terms */}
      <Text
        style={{
          fontFamily: 'OpenSans_400Regular',
          fontSize: 12,
          color: colors.inkGhost,
          textAlign: 'center',
          lineHeight: 18,
          marginBottom: 28,
