import React, { useState, useEffect, useCallback, useRef } from 'react';
import { View, Text, ScrollView, Pressable, TextInput, Platform, ActivityIndicator, useWindowDimensions, Image } from 'react-native';
import { SafeAreaView, useSafeAreaInsets } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { router } from 'expo-router';
import { useTheme } from '../../theme/ThemeContext';
import { useDebounce } from '../../hooks/useDebounce';
import { fetchSuggestions, fetchSearchResults, fetchVendorSearchResults, fetchTrendingSearches, SearchHit } from '../../api/search';
import { ProductCard } from '../../components/ProductCard';
import { useSearchStore } from '../../store/searchStore';
import { useEventStore } from '../../store/eventStore';

export default function Search() {
  const { colors } = useTheme();
  const [query, setQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [isLoadingSuggestions, setIsLoadingSuggestions] = useState(false);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [vendorSuggestions, setVendorSuggestions] = useState<any[]>([]);
  const [results, setResults] = useState<SearchHit[]>([]);
  const [vendorResults, setVendorResults] = useState<any[]>([]);
  const [hasSearched, setHasSearched] = useState(false);
  const [committedQuery, setCommittedQuery] = useState('');
  const committedQueryRef = useRef('');
  const hasSearchedRef = useRef(false);
  const [trendingSearches, setTrendingSearches] = useState<string[]>([]);
  
  const insets = useSafeAreaInsets();
  const { width } = useWindowDimensions();
  const isDesktop = width >= 768 && Platform.OS === 'web';
  const debouncedQuery = useDebounce(query, 300);

  const { recentSearches, addRecentSearch, clearRecentSearches } = useSearchStore();
  const addEvent = useEventStore((state) => state.addEvent);

  useEffect(() => {
    committedQueryRef.current = committedQuery;
  }, [committedQuery]);

  useEffect(() => {
    hasSearchedRef.current = hasSearched;
  }, [hasSearched]);

  // Fetch trending searches on mount
  useEffect(() => {
    let isMounted = true;
    fetchTrendingSearches().then(data => {
      if (isMounted) setTrendingSearches(data);
    });
    return () => { isMounted = false; };
  }, []);

  const getLocalSuggestions = useCallback((value: string) => {
    const normalized = value.trim().toLowerCase();
    if (!normalized) return [];

    return [...recentSearches, ...trendingSearches]
      .filter((item, index, source) => {
        const lowerItem = item.toLowerCase();
        return lowerItem.includes(normalized) && source.findIndex((candidate) => candidate.toLowerCase() === lowerItem) === index;
      })
      .slice(0, 8);
  }, [recentSearches, trendingSearches]);

  // YouTube-style behavior: typing previews suggestions, selection/submission performs the search.
  useEffect(() => {
    let isMounted = true;
    const trimmedQuery = debouncedQuery.trim();

    if (trimmedQuery.length > 0 && !hasSearched) {
      setHasSearched(false);
      setIsLoadingSuggestions(true);

      fetchSuggestions(trimmedQuery).then(data => {
        if (!isMounted || hasSearchedRef.current || trimmedQuery === committedQueryRef.current) return;

        const remoteSuggestions = data.suggestions || [];
        const remoteVendors = data.vendors || [];

        const localSuggestions = getLocalSuggestions(trimmedQuery);
        const mergedSuggestions = [trimmedQuery, ...remoteSuggestions, ...localSuggestions]
          .map((item) => item.trim())
          .filter(Boolean)
          .filter((item, index, source) => source.findIndex((candidate) => candidate.toLowerCase() === item.toLowerCase()) === index)
          .slice(0, 8);

        setSuggestions(mergedSuggestions);
        setVendorSuggestions(remoteVendors);
        setIsLoadingSuggestions(false);
      });
    } else if (trimmedQuery.length > 0) {
      setSuggestions([]);
      setVendorSuggestions([]);
      setIsLoadingSuggestions(false);
    } else {
      setHasSearched(false);
      setResults([]);
      setVendorResults([]);
      setSuggestions([]);
      setVendorSuggestions([]);
      setCommittedQuery('');
      setIsLoadingSuggestions(false);
    }
    return () => { isMounted = false; };
  }, [debouncedQuery, getLocalSuggestions, hasSearched]);

  const handleSearchSubmit = async (searchQuery: string) => {
    const trimmedQuery = searchQuery.trim();
    if (!trimmedQuery) return;
    
    setQuery(trimmedQuery);
    setSuggestions([]);
    setVendorSuggestions([]);
    setCommittedQuery(trimmedQuery);
    
    addRecentSearch(trimmedQuery);
    
    addEvent({
      event_type: 'product_search',
      metadata: { query: trimmedQuery }
    });
    
    // Explicitly fetch on submit for instant feedback, though useEffect handles debounced
    setHasSearched(true);
    setIsSearching(true);
    
    const [response, vendorResponse] = await Promise.all([
      fetchSearchResults(trimmedQuery),
      fetchVendorSearchResults(trimmedQuery)
    ]);

    if (response && response.hits) {
      setResults(response.hits);
    } else {
      setResults([]);
    }

    if (vendorResponse && vendorResponse.hits) {
      setVendorResults(vendorResponse.hits.map((h: any) => h.document));
    } else {
      setVendorResults([]);
    }

    setIsSearching(false);
  };

  const handleClear = () => {
    setQuery('');
    setHasSearched(false);
    setResults([]);
    setVendorResults([]);
    setSuggestions([]);
    setVendorSuggestions([]);
    setCommittedQuery('');
  };

  const handleSuggestionFill = (searchQuery: string) => {
    setQuery(searchQuery);
    setHasSearched(false);
  };

  const renderSuggestionText = (suggestion: string) => {
    const trimmedQuery = query.trim();
    const matchIndex = suggestion.toLowerCase().indexOf(trimmedQuery.toLowerCase());

    if (!trimmedQuery || matchIndex < 0) {
      return (
        <Text style={{ fontFamily: 'OpenSans_600SemiBold', fontSize: 15, color: colors.ink }}>
          {suggestion}
        </Text>
      );
    }

    const beforeMatch = suggestion.slice(0, matchIndex);
    const match = suggestion.slice(matchIndex, matchIndex + trimmedQuery.length);
    const afterMatch = suggestion.slice(matchIndex + trimmedQuery.length);

    return (
      <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 15, color: colors.ink }}>
        {beforeMatch}
        <Text style={{ fontFamily: 'OpenSans_600SemiBold', color: colors.ink }}>{match}</Text>
        {afterMatch}
      </Text>
    );
  };

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: colors.surface }} edges={['top']}>
      <View style={{ paddingHorizontal: 24, paddingTop: 24, paddingBottom: 16 }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 24 }}>
          <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 26, color: colors.ink, flex: 1 }}>
            Search
          </Text>
        </View>

        <View style={{
          flexDirection: 'row',
          alignItems: 'center',
          backgroundColor: colors.surfaceSoft,
          borderWidth: 1.5,
          borderColor: colors.surfaceMuted,
          height: 52,
          borderRadius: 26,
          paddingHorizontal: 16,
        }}>
          <Ionicons name="search" size={20} color={colors.inkMuted} />
          <TextInput 
            value={query}
            onChangeText={(text) => {
              setQuery(text);
              setHasSearched(false);
              setCommittedQuery('');
            }}
            onSubmitEditing={() => handleSearchSubmit(query)}
            placeholder="What are you looking for?"
            style={{ 
              flex: 1, height: '100%', marginLeft: 10, fontFamily: 'OpenSans_400Regular', fontSize: 15, color: colors.ink,
              ...Platform.select({ web: { outlineStyle: 'none' }, default: {} })
            } as any}
            placeholderTextColor={colors.inkGhost}
            returnKeyType="search"
          />
          {query.length > 0 && (
            <Pressable onPress={handleClear}>
              <Ionicons name="close-circle" size={20} color={colors.inkGhost} />
            </Pressable>
          )}
        </View>
      </View>

      <ScrollView 
        style={{ flex: 1 }} 
        showsVerticalScrollIndicator={false} 
        contentContainerStyle={{ paddingBottom: insets.bottom + 100 }}
        keyboardShouldPersistTaps="handled"
      >
        {query.length === 0 ? (
          <View style={{ paddingHorizontal: 24, paddingTop: 16 }}>
            {/* Recent Searches */}
            <View style={{ marginBottom: 32 }}>
              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
                <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 18, color: colors.ink }}>Recent</Text>
                <Pressable onPress={clearRecentSearches}>
                  <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 13, color: colors.inkMuted }}>Clear</Text>
                </Pressable>
              </View>
              {recentSearches.map((item, index) => (
                <Pressable 
                  key={index}
                  style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: colors.surfaceMuted }}
                  onPress={() => handleSearchSubmit(item)}
                >
                  <Ionicons name="time-outline" size={20} color={colors.inkGhost} style={{ marginRight: 12 }} />
                  <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 15, color: colors.inkSoft, flex: 1 }}>{item}</Text>
                  <Ionicons name="chevron-forward" size={16} color={colors.surfaceMuted} />
                </Pressable>
              ))}
            </View>

            {/* Trending Searches */}
            <View>
              <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 18, color: colors.ink, marginBottom: 16 }}>Trending Now</Text>
              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 12 }}>
                {trendingSearches.map((item, index) => (
                  <Pressable
                    key={index}
                    style={{
                      backgroundColor: colors.surfaceSoft,
                      paddingHorizontal: 16,
                      paddingVertical: 10,
                      borderRadius: 20,
                      flexDirection: 'row',
                      alignItems: 'center',
                    }}
                    onPress={() => handleSearchSubmit(item)}
                  >
                    <Ionicons name="trending-up" size={16} color={colors.inkMuted} style={{ marginRight: 6 }} />
                    <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 13, color: colors.inkSoft }}>{item}</Text>
                  </Pressable>
                ))}
              </View>
            </View>
          </View>
        ) : !hasSearched ? (
          <View style={{ paddingTop: 4 }}>
            {suggestions.length > 0 ? (
              suggestions.map((item, index) => (
                <Pressable
                  key={`${item}-${index}`}
                  style={({ pressed }) => ({
                    minHeight: 50,
                    paddingHorizontal: 24,
                    flexDirection: 'row',
                    alignItems: 'center',
                    backgroundColor: pressed ? colors.surfaceSoft : colors.surface,
                  })}
                  onPress={() => handleSearchSubmit(item)}
                >
                  <Ionicons name="search-outline" size={20} color={colors.inkMuted} style={{ marginRight: 16 }} />
                  <View style={{ flex: 1 }}>
                    {renderSuggestionText(item)}
                  </View>
                  <Pressable
                    accessibilityLabel={`Fill search with ${item}`}
                    hitSlop={12}
                    onPress={(event) => {
                      event.stopPropagation();
                      handleSuggestionFill(item);
                    }}
                    style={{ width: 44, height: 44, alignItems: 'center', justifyContent: 'center', marginRight: -12 }}
                  >
                    <Ionicons name="arrow-up-outline" size={18} color={colors.inkMuted} style={{ transform: [{ rotate: '-45deg' }] }} />
                  </Pressable>
                </Pressable>
              ))
            ) : null}

            {vendorSuggestions.length > 0 && (
              <View style={{ paddingHorizontal: 24, paddingTop: 16, paddingBottom: 8 }}>
                <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 14, color: colors.inkMuted, marginBottom: 12 }}>
                  Stores
                </Text>
                {vendorSuggestions.map((vendor, index) => (
                  <Pressable
                    key={`vendor-${vendor.id}`}
                    style={({ pressed }) => ({
                      flexDirection: 'row',
                      alignItems: 'center',
                      paddingVertical: 12,
                      opacity: pressed ? 0.7 : 1,
                    })}
                    onPress={() => router.push(`/vendor/${vendor.id}` as any)}
                  >
                    {vendor.logo_url ? (
                      <Image source={{ uri: vendor.logo_url }} style={{ width: 24, height: 24, borderRadius: 12, marginRight: 16 }} />
                    ) : (
                      <Ionicons name="storefront-outline" size={24} color={colors.inkSoft} style={{ marginRight: 16 }} />
                    )}
                    <View style={{ flex: 1 }}>
                      <Text style={{ fontFamily: 'OpenSans_600SemiBold', fontSize: 15, color: colors.ink }}>
                        {vendor.store_name}
                      </Text>
                      {vendor.bio && (
                        <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.inkMuted }} numberOfLines={1}>
                          {vendor.bio}
                        </Text>
                      )}
                    </View>
                    <Ionicons name="chevron-forward" size={16} color={colors.surfaceMuted} />
                  </Pressable>
                ))}
              </View>
            )}

            {suggestions.length === 0 && vendorSuggestions.length === 0 && (
              <View style={{ paddingHorizontal: 24, paddingTop: 28 }}>
                <View style={{
                  minHeight: 72,
                  borderRadius: 16,
                  backgroundColor: colors.surfaceSoft,
                  borderWidth: 1,
                  borderColor: colors.surfaceMuted,
                  paddingHorizontal: 16,
                  flexDirection: 'row',
                  alignItems: 'center',
                }}>
                  <Ionicons name={isLoadingSuggestions ? 'hourglass-outline' : 'search-outline'} size={22} color={colors.inkMuted} style={{ marginRight: 12 }} />
                  <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 14, color: colors.inkMuted, flex: 1 }}>
                    {isLoadingSuggestions ? 'Finding suggestions...' : 'Press search to look for this.'}
                  </Text>
                </View>
              </View>
            )}
          </View>
        ) : hasSearched ? (
          <View style={{ paddingHorizontal: 24, paddingTop: 16 }}>
            <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 18, color: colors.ink, marginBottom: 16 }}>
              Results for "{committedQuery || query}"
            </Text>
            
            {isSearching ? (
              <View style={{ padding: 40, alignItems: 'center' }}>
                <ActivityIndicator size="large" color={colors.primary} />
              </View>
            ) : (
              <>
                {vendorResults.length > 0 && (
                  <View style={{ marginBottom: 24 }}>
                    <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 16, color: colors.ink, marginBottom: 12 }}>
                      Stores
                    </Text>
                    <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 16 }}>
                      {vendorResults.map(vendor => (
                        <Pressable
                          key={vendor.id}
                          style={({ pressed }) => ({
                            width: 200,
                            backgroundColor: colors.surfaceSoft,
                            borderRadius: 12,
                            padding: 16,
                            opacity: pressed ? 0.8 : 1,
                            borderWidth: 1,
                            borderColor: colors.surfaceMuted,
                          })}
                          onPress={() => router.push(`/vendor/${vendor.id}` as any)}
                        >
                          <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 8 }}>
                            {vendor.logo_url ? (
                              <Image source={{ uri: vendor.logo_url }} style={{ width: 40, height: 40, borderRadius: 20, marginRight: 12 }} />
                            ) : (
                              <View style={{ width: 40, height: 40, borderRadius: 20, backgroundColor: colors.surface, alignItems: 'center', justifyContent: 'center', marginRight: 12 }}>
                                <Ionicons name="storefront" size={20} color={colors.primary} />
                              </View>
                            )}
                            <View style={{ flex: 1 }}>
                              <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 15, color: colors.ink }} numberOfLines={1}>
                                {vendor.store_name}
                              </Text>
                            </View>
                          </View>
                          {vendor.bio && (
                            <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.inkMuted }} numberOfLines={2}>
                              {vendor.bio}
                            </Text>
                          )}
                        </Pressable>
                      ))}
                    </ScrollView>
                  </View>
                )}
                
                {results.length > 0 ? (
                  <View>
                    <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 16, color: colors.ink, marginBottom: 12 }}>
                      Products
                    </Text>
                    <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 16 }}>
                      {results.map((hit) => {
                  const p = hit.document;
                  return (
                    <View key={p.id} style={{ width: isDesktop ? '31%' : '100%', marginBottom: 16 }}>
                      <ProductCard
                        id={p.id}
                        name={p.name}
                        price={p.price}
                        salePrice={p.discount_price}
                        imageUrl={p.image_url || 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=800&q=80'}
                        vendorId={p.vendor_id}
                        vendorName="View Store"
                        onPress={() => router.push(`/product/${p.id}` as any)}
                      />
                    </View>
                  );
                })}
                    </View>
                  </View>
            ) : vendorResults.length === 0 ? (
              <View style={{ padding: 40, alignItems: 'center' }}>
                <Ionicons name="search" size={48} color={colors.surfaceMuted} style={{ marginBottom: 16 }} />
                <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 16, color: colors.inkMuted }}>
                  No products or stores found.
                </Text>
              </View>
            ) : null}
            </>
            )}
          </View>
        ) : (
          <View style={{ flex: 1 }} />
        )}
      </ScrollView>
    </SafeAreaView>
  );
}

import { Stack } from "expo-router";
import { SidebarProvider } from '../context/SidebarContext';
import { Sidebar } from '../components/Sidebar';
import "../../global.css";
import { useFonts } from 'expo-font';
import { Inter_400Regular, Inter_500Medium, Inter_600SemiBold, Inter_700Bold } from '@expo-google-fonts/inter';
import { OpenSans_400Regular, OpenSans_600SemiBold } from '@expo-google-fonts/open-sans';
import * as SplashScreen from 'expo-splash-screen';
import { useEffect } from 'react';
import { ThemeProvider } from '../theme/ThemeContext';
import {
  useQuery,
  useMutation,
  useQueryClient,
  QueryClient,
  QueryClientProvider,
} from '@tanstack/react-query'
import { AuthProvider } from '../context/AuthContext';
import { ToastProvider } from '../context/ToastContext';
import { WebSocketProvider } from '../context/WebSocketContext';
import { EventTracker } from '../components/EventTracker';


SplashScreen.preventAutoHideAsync();

// Must be created outside the component to avoid re-creation on every render
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 1000 * 60 * 5, // 5 minutes
      retry: 1,
    },
  },
});

export default function RootLayout() {

  const [loaded, error] = useFonts({
    'Inter_400Regular': Inter_400Regular,
    'Inter_500Medium': Inter_500Medium,
    'Inter_600SemiBold': Inter_600SemiBold,
    'Inter_700Bold': Inter_700Bold,
    'OpenSans_400Regular': OpenSans_400Regular,
    'OpenSans_600SemiBold': OpenSans_600SemiBold,
  });

  useEffect(() => {
    if (loaded || error) {
      SplashScreen.hideAsync();
    }
  }, [loaded, error]);

  if (!loaded && !error) {
    return null;
  }

function NotificationManager() {
  const { useNotifications } = require('../hooks/useNotifications');
  useNotifications();
  return null;
}

  return (
    <QueryClientProvider client={queryClient}>
      <ThemeProvider>
        <AuthProvider>
          <WebSocketProvider>
            <ToastProvider>
              <EventTracker />
              <NotificationManager />
              <SidebarProvider>
              <Stack screenOptions={{ headerShown: false }}>
                <Stack.Screen name="index" />
                <Stack.Screen name="(auth)" />
                <Stack.Screen name="(tabs)" />
                <Stack.Screen name="suspended" />
              </Stack>
              <Sidebar />
            </SidebarProvider>
          </ToastProvider>
          </WebSocketProvider>
        </AuthProvider>
      </ThemeProvider>
    </QueryClientProvider>
  );
}

import React, { useState, useEffect, useContext, useCallback } from 'react';
import { View, Text, ScrollView, Pressable, Platform, useWindowDimensions, ActivityIndicator, TextInput } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { router } from 'expo-router';
import { useTheme } from '../theme/ThemeContext';
import { Button } from '../components/Button';
import { WebHeader } from '../components/WebHeader';
import { useToast } from '../context/ToastContext';
import { useCartStore } from '../store/cartStore';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { saveLocalOrder } from '../api/localOrders';
import { useQueryClient } from '@tanstack/react-query';
import { AuthContext } from '../context/AuthContext';
import { MapView } from '../components/Map/MapView';
import { MapMarker } from '../components/Map/MapMarker';
import { LocationSearchModal, LocationResult } from '../components/LocationSearchModal';
import * as Location from 'expo-location';

async function reverseGeocodeAddress(lat: number, lng: number) {
  if (Platform.OS === 'web') {
    const res = await fetch(
      `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`,
      { headers: { 'Accept-Language': 'en', 'User-Agent': 'ElectricApp/1.0' } }
    );
    const data = await res.json();
    const a = data?.address;
    return {
      street: `${a?.house_number || ''} ${a?.road || ''}`.trim() || 'Unknown Street',
      city: `${a?.city || a?.town || a?.village || ''}, ${a?.state || ''} ${a?.postcode || ''}`.trim(),
    };
  } else {
    return null;
  }
}

const BASE_URL = process.env.EXPO_PUBLIC_API_BASE_URL ?? 'http://127.0.0.1:8000';

interface Address {
  id: string;
  name: string;
  street: string;
  city: string;
  lat?: number;
  lng?: number;
  landmark?: string;
  isDefault?: boolean;
}

interface PaymentMethod {
  id: string;
  type: string;
  last4: string;
  expiry: string;
  isDefault?: boolean;
}

export default function CheckoutScreen() {
  const { colors } = useTheme();
  const { width } = useWindowDimensions();
  const isDesktop = width >= 768 && Platform.OS === 'web';
  const { showToast } = useToast();
  const clearCart = useCartStore(state => state.clearCart);
  const cartItems = useCartStore(state => state.items);
  const getSubtotal = useCartStore(state => state.getSubtotal);
  const queryClient = useQueryClient();
  const { token } = React.useContext(AuthContext);

  const [step, setStep] = useState(1);
  const [addresses, setAddresses] = useState<Address[]>([]);
  const [payments, setPayments] = useState<PaymentMethod[]>([]);
  const [selectedAddressId, setSelectedAddressId] = useState<string | null>(null);
  const [selectedPaymentId, setSelectedPaymentId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [orderRef, setOrderRef] = useState<string | null>(null);
  const [showLocationSearch, setShowLocationSearch] = useState(false);
  const [landmark, setLandmark] = useState('');
  const [phone, setPhone] = useState('');
  const [mapCenter, setMapCenter] = useState<{ latitude: number; longitude: number }>({ latitude: 5.6037, longitude: -0.1870 });
  const [mapReady, setMapReady] = useState(false);

  // Fetch user location once on mount to center the map
  useEffect(() => {
    (async () => {
      try {
        const { status } = await Location.requestForegroundPermissionsAsync();
        if (status === 'granted') {
          const loc = await Location.getCurrentPositionAsync({ accuracy: Location.Accuracy.Balanced });
          setMapCenter({ latitude: loc.coords.latitude, longitude: loc.coords.longitude });
        }
      } catch (e) {
        // silently fall back to default Accra coords
      } finally {
        setMapReady(true);
      }
    })();
  }, []);

  const SHIPPING_FEE = 4.99;
  const subtotal = getSubtotal();
  const total = subtotal + SHIPPING_FEE;

  const selectedAddressIdRef = React.useRef<string | null>(null);
  const selectedPaymentIdRef = React.useRef<string | null>(null);

  // Load saved addresses & payments once on mount only — NOT on every focus,
  // so that in-memory pinned addresses don't get wiped by a re-load.
  useEffect(() => {
    async function loadData() {
      try {
        const [addrData, payData] = await Promise.all([
          AsyncStorage.getItem('@user_addresses'),
          AsyncStorage.getItem('@user_payments'),
        ]);
        const addrs: Address[] = addrData ? JSON.parse(addrData) : [];
        const pays: PaymentMethod[] = payData ? JSON.parse(payData) : [];

        setAddresses(addrs);
        setPayments(pays);

        // Auto-select default only if nothing is selected yet
        if (!selectedAddressIdRef.current) {
          const defaultAddr = addrs.find(a => a.isDefault) ?? addrs[0];
          if (defaultAddr) {
            setSelectedAddressId(defaultAddr.id);
            selectedAddressIdRef.current = defaultAddr.id;
          }
        }
        if (!selectedPaymentIdRef.current) {
          const defaultPay = pays.find(p => p.isDefault) ?? pays[0];
          if (defaultPay) {
            setSelectedPaymentId(defaultPay.id);
            selectedPaymentIdRef.current = defaultPay.id;
          }
        }
      } catch (e) {
        console.error('Failed to load checkout data', e);
      } finally {
        setIsLoading(false);
      }
    }
    loadData();
  }, []); // empty deps — run once on mount only

  const selectedAddress = addresses.find(a => a.id === selectedAddressId);
  const selectedPayment = payments.find(p => p.id === selectedPaymentId);

  const handlePlaceOrder = async () => {
    if (!selectedAddressId) {
      showToast('Please select a shipping address.', 'warning');
      return;
    }
    if (!selectedPaymentId) {
      showToast('Please select a payment method.', 'warning');
      return;
    }
    if (cartItems.length === 0) {
      showToast('Your cart is empty.', 'warning');
      return;
    }

    setIsLoading(true);
    try {
      // Build the backend order payload
      const orderPayload = {
        shipping_address: {
          name: selectedAddress?.name ?? '',
          street: selectedAddress?.street ?? '',
          city: selectedAddress?.city ?? '',
          phone: phone,
          landmark: landmark,
        },
        notes: null,
        items: cartItems.map(item => ({
          product_id: item.id,
          quantity: item.quantity,
          color_chosen: null,
        })),
      };

      // POST to the real backend
      const res = await fetch(`${BASE_URL}/orders/`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify(orderPayload),
      });

      if (!res.ok) {
        let detail: any;
        try { detail = await res.json(); } catch { detail = { detail: res.statusText }; }
        let errorMsg = detail?.detail;
        if (Array.isArray(errorMsg)) {
          errorMsg = errorMsg.map((e: any) => e.msg).join(', ');
        }
        throw new Error(errorMsg ?? `Order failed (${res.status})`);
      }

      const backendOrder = await res.json();

      const realRef = backendOrder.id.slice(-8).toUpperCase();
      setOrderRef(realRef);

      // Also save a local copy for offline order-tracking page
      const now = new Date().toISOString();
      await saveLocalOrder({
        id: backendOrder.id,
        ref: realRef,
        status: backendOrder.status,
        subtotal,
        shipping_fee: SHIPPING_FEE,
        total_amount: total,
        delivery_pin: backendOrder.delivery_pin,
        discount_amount: backendOrder.discount_amount ?? 0,
        shipping_address: {
          name: selectedAddress?.name ?? '',
          street: selectedAddress?.street ?? '',
          city: selectedAddress?.city ?? '',
          lat: selectedAddress?.lat,
          lng: selectedAddress?.lng,
          phone: phone,
          landmark: landmark,
        },
        vendor_id: cartItems[0]?.vendorId ?? '',
        payment: {
          type: selectedPayment?.type ?? '',
          last4: selectedPayment?.last4 ?? '',
        },
        items: cartItems.map(item => ({
          id: `item-${item.id}`,
          product_id: item.id,
          name: item.name,
          imageUrl: item.imageUrl,
          quantity: item.quantity,
          unit_price: item.price,
          discount_price: item.salePrice ?? null,
        })),
        created_at: backendOrder.created_at ?? now,
        updated_at: backendOrder.updated_at ?? now,
      });

      // Clear the cart and refresh queries
      clearCart();
      
      if (selectedAddress?.lat && selectedAddress?.lng) {
        await AsyncStorage.setItem('@active_delivery', JSON.stringify({
          lat: selectedAddress.lat,
          lng: selectedAddress.lng,
          vendorId: cartItems[0]?.vendorId ?? ''
        }));
      }

      queryClient.invalidateQueries({ queryKey: ['local-orders'] });
      queryClient.invalidateQueries({ queryKey: ['vendor-orders'] });
      queryClient.invalidateQueries({ queryKey: ['vendor-analytics'] });
      showToast('Order placed successfully!', 'success');
      setStep(3);
    } catch (err: any) {
      showToast(err?.message ?? 'Failed to place order. Please try again.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  if (isLoading) {
    return (
      <SafeAreaView style={{ flex: 1, backgroundColor: colors.surfaceSoft, justifyContent: 'center', alignItems: 'center' }} edges={['top']}>
        <ActivityIndicator size="large" color={colors.primary} />
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: colors.surfaceSoft }} edges={['top']}>
      {isDesktop && <WebHeader />}

      <View style={{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: 24, paddingVertical: 16, backgroundColor: colors.surface, borderBottomWidth: 1, borderBottomColor: colors.surfaceMuted }}>
        <Pressable onPress={() => router.canGoBack() ? router.back() : router.replace('/(tabs)/cart')} style={{ padding: 8, marginRight: 8, marginLeft: -8 }}>
          <Ionicons name="arrow-back" size={24} color={colors.ink} />
        </Pressable>
        <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 20, color: colors.ink, flex: 1 }}>Checkout</Text>

        {/* Step indicator */}
        {step < 3 && (
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
            {[1, 2].map(s => (
              <React.Fragment key={s}>
                <View style={{ width: 28, height: 28, borderRadius: 14, backgroundColor: s <= step ? colors.ink : colors.surfaceMuted, alignItems: 'center', justifyContent: 'center' }}>
                  <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 12, color: s <= step ? colors.surface : colors.inkGhost }}>{s}</Text>
                </View>
                {s < 2 && <View style={{ width: 20, height: 2, backgroundColor: step > 1 ? colors.ink : colors.surfaceMuted, borderRadius: 1 }} />}
              </React.Fragment>
            ))}
          </View>
        )}
      </View>

      <ScrollView style={{ flex: 1 }} contentContainerStyle={{ padding: 24, maxWidth: 600, alignSelf: 'center', width: '100%' }}>

        {/* ─── Step 1: Address ─── */}
        {step === 1 && (
          <View>
            <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 18, color: colors.ink, marginBottom: 16 }}>Shipping Address</Text>

            {/* Map Container */}
            <View style={{ height: 250, width: '100%', borderRadius: 16, overflow: 'hidden', marginBottom: 16, borderWidth: 1, borderColor: colors.surfaceMuted }}>
              {mapReady ? (
                <MapView
                  style={{ flex: 1, width: '100%', height: '100%' }}
                  mapStyle="https://tiles.openfreemap.org/styles/liberty"
                  initialRegion={{
                    latitude: selectedAddress?.lat ?? mapCenter.latitude,
                    longitude: selectedAddress?.lng ?? mapCenter.longitude,
                    zoom: 14
                  }}
                  showUserLocation
                  onPress={async (feature) => {
                    if (feature?.geometry?.coordinates) {
                      const [lng, lat] = feature.geometry.coordinates;
                      let street = 'Selected Location';
                      let city = '';
                      const webResult = await reverseGeocodeAddress(lat, lng);
                      if (webResult) {
                        street = webResult.street;
                        city = webResult.city;
                      } else {
                        try {
                          const geocode = await Location.reverseGeocodeAsync({ latitude: lat, longitude: lng });
                          if (geocode.length > 0) {
                            const place = geocode[0];
                            street = `${place.streetNumber || ''} ${place.street || ''}`.trim() || 'Selected Location';
                            city = `${place.city || ''}, ${place.region || ''} ${place.postalCode || ''}`.trim();
                          }
                        } catch (e) {}
                      }
                      const newId = Date.now().toString();
                      const newAddr = { id: newId, name: 'Pinned Location', street, city, lat, lng };
                      setAddresses(prev => [newAddr, ...prev]);
                      setSelectedAddressId(newId);
                    }
                  }}
                >
                  {selectedAddress && selectedAddress.lat && selectedAddress.lng && (
                    <MapMarker
                      id="selected-address"
                      coordinate={[selectedAddress.lng, selectedAddress.lat]}
                      title={selectedAddress.name}
                    >
                      <View style={{ width: 40, height: 40, alignItems: 'center', justifyContent: 'flex-end' }}>
                        <Ionicons name="location" size={40} color={colors.primary} style={Platform.OS === 'web' ? { filter: 'drop-shadow(0px 2px 4px rgba(0,0,0,0.3))' } as any : { shadowColor: '#000', shadowOpacity: 0.3, shadowRadius: 4, elevation: 4 }} />
                      </View>
                    </MapMarker>
                  )}
                </MapView>
              ) : (
                <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', backgroundColor: colors.surfaceSoft }}>
                  <ActivityIndicator size="large" color={colors.primaryDim} />
                  <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.inkMuted, marginTop: 8 }}>Locating you…</Text>
                </View>
              )}
            </View>

            <Pressable
              onPress={() => setShowLocationSearch(true)}
              style={({ pressed }) => ({
                backgroundColor: pressed ? colors.surfaceSoft : colors.surface,
                padding: 16, borderRadius: 16, borderWidth: 1, borderColor: colors.surfaceMuted,
                alignItems: 'center', justifyContent: 'center', flexDirection: 'row', marginBottom: 16
              })}
            >
              <Ionicons name="search" size={20} color={colors.ink} style={{ marginRight: 8 }} />
              <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 15, color: colors.ink }}>Search for Address</Text>
            </Pressable>

            {addresses.length === 0 ? (
              <View style={{ backgroundColor: colors.surface, borderRadius: 16, padding: 24, alignItems: 'center', borderWidth: 1, borderColor: colors.surfaceMuted, marginBottom: 16 }}>
                <Ionicons name="location-outline" size={36} color={colors.surfaceMuted} style={{ marginBottom: 8 }} />
                <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 15, color: colors.inkMuted }}>No saved addresses</Text>
              </View>
            ) : (
              <ScrollView style={{ maxHeight: 200, marginBottom: 16 }} nestedScrollEnabled>
                <View style={{ gap: 12 }}>
                  {addresses.map(addr => {
                    const sel = addr.id === selectedAddressId;
                    return (
                      <Pressable key={addr.id} onPress={() => setSelectedAddressId(addr.id)} style={{
                        backgroundColor: colors.surface, borderRadius: 16, padding: 16,
                        borderWidth: 1.5, borderColor: sel ? colors.primary : colors.surfaceMuted,
                      }}>
                        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 4 }}>
                          <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                            <Ionicons name={addr.name === 'Home' ? 'home' : 'location'} size={16} color={sel ? colors.primaryDim : colors.ink} style={{ marginRight: 8 }} />
                            <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 15, color: colors.ink }}>{addr.name}</Text>
                          </View>
                          {sel && <Ionicons name="checkmark-circle" size={22} color={colors.primary} />}
                        </View>
                        <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.inkMuted }}>{addr.street}</Text>
                        <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.inkMuted }}>{addr.city}</Text>
                      </Pressable>
                    );
                  })}
                </View>
              </ScrollView>
            )}

            <View style={{ marginBottom: 16 }}>
              <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 14, color: colors.ink, marginBottom: 8 }}>Phone Number</Text>
              <TextInput
                style={{
                  backgroundColor: colors.surface, borderRadius: 12, paddingHorizontal: 16, height: 48,
                  borderWidth: 1, borderColor: colors.surfaceMuted, fontFamily: 'Inter_600SemiBold', fontSize: 15, color: colors.ink,
                  ...Platform.select({ web: { outlineStyle: 'none' }, default: {} }) as any
                }}
                placeholder="e.g. 055 123 4567"
                placeholderTextColor={colors.inkGhost}
                keyboardType="phone-pad"
                value={phone}
                onChangeText={setPhone}
              />
            </View>

            <View style={{ marginBottom: 32 }}>
              <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 14, color: colors.ink, marginBottom: 8 }}>Landmark (Optional, but recommended)</Text>
              <TextInput
                style={{
                  backgroundColor: colors.surface, borderRadius: 12, paddingHorizontal: 16, height: 48,
                  borderWidth: 1, borderColor: colors.surfaceMuted, fontFamily: 'OpenSans_400Regular', fontSize: 15, color: colors.ink,
                  ...Platform.select({ web: { outlineStyle: 'none' }, default: {} }) as any
                }}
                placeholder="e.g. Near the big bus stop"
                placeholderTextColor={colors.inkGhost}
                value={landmark}
                onChangeText={setLandmark}
              />
              <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 12, color: colors.inkMuted, marginTop: 4 }}>
                Help the vendor locate you easily in case they find it difficult to track your current location.
              </Text>
            </View>

            <Button title="Continue to Payment" onPress={() => {
              if (!selectedAddressId) { showToast('Please select a shipping address.', 'warning'); return; }
              if (!phone) { showToast('Please provide a phone number for delivery.', 'warning'); return; }
              setStep(2);
            }} />
          </View>
        )}

        {/* ─── Step 2: Payment + Summary ─── */}
        {step === 2 && (
          <View>
            <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 18, color: colors.ink, marginBottom: 16 }}>Payment Method</Text>

            {payments.length === 0 ? (
              <View style={{ backgroundColor: colors.surface, borderRadius: 16, padding: 24, alignItems: 'center', borderWidth: 1, borderColor: colors.surfaceMuted, marginBottom: 16 }}>
                <Ionicons name="card-outline" size={36} color={colors.surfaceMuted} style={{ marginBottom: 8 }} />
                <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 15, color: colors.inkMuted }}>No saved payment methods</Text>
              </View>
            ) : (
              <View style={{ gap: 12, marginBottom: 16 }}>
                {payments.map(pay => {
                  const sel = pay.id === selectedPaymentId;
                  return (
                    <Pressable key={pay.id} onPress={() => setSelectedPaymentId(pay.id)} style={{
                      backgroundColor: colors.surface, borderRadius: 16, padding: 16,
                      borderWidth: 1.5, borderColor: sel ? colors.primary : colors.surfaceMuted,
                    }}>
                      <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>
