import React, { useState, useEffect } from 'react';
import { View, Text, ScrollView, Pressable, Platform, useWindowDimensions, Image } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { router } from 'expo-router';
import { useTheme } from '../theme/ThemeContext';
import { ProductCard } from '../components/ProductCard';
import { useQuery } from '@tanstack/react-query';
import { listProducts, mapProductToCard } from '../api/products';

// Removed static FLASH_PRODUCTS

// End time: 6 hours from now
const END_TIME = Date.now() + 6 * 60 * 60 * 1000;

function useCountdown(targetMs: number) {
  const [remaining, setRemaining] = useState(targetMs - Date.now());
  useEffect(() => {
    const interval = setInterval(() => setRemaining(targetMs - Date.now()), 1000);
    return () => clearInterval(interval);
  }, [targetMs]);
  const total = Math.max(0, remaining);
  const h = Math.floor(total / 3600000).toString().padStart(2, '0');
  const m = Math.floor((total % 3600000) / 60000).toString().padStart(2, '0');
  const s = Math.floor((total % 60000) / 1000).toString().padStart(2, '0');
  return { h, m, s };
}

function TimeUnit({ value, label, colors }: { value: string; label: string; colors: any }) {
  return (
    <View style={{ alignItems: 'center', marginHorizontal: 8 }}>
      <View style={{ backgroundColor: colors.ink, paddingHorizontal: 16, paddingVertical: 10, borderRadius: 12, minWidth: 56, alignItems: 'center' }}>
        <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 28, color: colors.surface }}>{value}</Text>
      </View>
      <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 11, color: colors.inkGhost, marginTop: 6, textTransform: 'uppercase', letterSpacing: 1 }}>{label}</Text>
    </View>
  );
}

export default function FlashSalesScreen() {
  const { colors } = useTheme();
  const { width } = useWindowDimensions();
  const isDesktop = width >= 768 && Platform.OS === 'web';
  const { h, m, s } = useCountdown(END_TIME);

  const { data: products = [], isLoading } = useQuery({
    queryKey: ['flash-products'],
    queryFn: () => listProducts({ limit: 100 }),
  });

  // Filter products that have a discount
  const flashProducts = products
    .filter(p => p.discount_price != null && p.discount_price < p.actual_price)
    .map(mapProductToCard)
    .slice(0, 10); // Limit to top 10 flash sales

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: colors.surfaceSoft }} edges={['top']}>
      {/* Header */}
      <View style={{
        backgroundColor: colors.surface,
        borderBottomWidth: 1,
        borderBottomColor: colors.surfaceMuted,
        paddingBottom: 0,
      }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: 20, paddingVertical: 16 }}>
          <Pressable onPress={() => router.canGoBack() ? router.back() : router.replace('/(tabs)')} style={{ marginRight: 12, padding: 4 }}>
            <Ionicons name="arrow-back" size={24} color={colors.ink} />
          </Pressable>
          <View style={{ flex: 1 }}>
            <View style={{ flexDirection: 'row', alignItems: 'center' }}>
              <Ionicons name="flash" size={22} color="#f59e0b" style={{ marginRight: 8 }} />
              <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 22, color: colors.ink }}>Flash Sale</Text>
            </View>
            <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 12, color: colors.inkMuted, marginTop: 2 }}>
              Limited time, limited stock — grab it before it's gone!
            </Text>
          </View>
        </View>

        {/* Countdown Banner */}
        <View style={{ backgroundColor: colors.isDark ? '#1a0a00' : '#fff8ed', paddingVertical: 20, alignItems: 'center', borderTopWidth: 1, borderTopColor: colors.isDark ? '#2d1500' : '#fde68a40' }}>
          <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 12, color: '#b45309', marginBottom: 12, textTransform: 'uppercase', letterSpacing: 1.5 }}>
            Ends In
          </Text>
          <View style={{ flexDirection: 'row', alignItems: 'center' }}>
            <TimeUnit value={h} label="Hours" colors={colors} />
            <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 28, color: colors.inkMuted, marginBottom: 18 }}>:</Text>
            <TimeUnit value={m} label="Mins" colors={colors} />
            <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 28, color: colors.inkMuted, marginBottom: 18 }}>:</Text>
            <TimeUnit value={s} label="Secs" colors={colors} />
          </View>
        </View>
      </View>

      <ScrollView style={{ flex: 1 }} contentContainerStyle={{ padding: 20 }}>
        <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 16 }}>
          {isLoading ? (
            <Text style={{ fontFamily: 'OpenSans_400Regular', color: colors.inkMuted, textAlign: 'center', width: '100%', marginTop: 24 }}>Loading flash sales...</Text>
          ) : flashProducts.length === 0 ? (
            <Text style={{ fontFamily: 'OpenSans_400Regular', color: colors.inkMuted, textAlign: 'center', width: '100%', marginTop: 24 }}>No active flash sales right now.</Text>
          ) : flashProducts.map(product => (
            <View key={product.id} style={{ width: isDesktop ? '31%' : '100%' }}>
              {/* Stock badge */}
              {!product.inStock && (
                <View style={{ backgroundColor: '#fef2f2', borderRadius: 8, paddingHorizontal: 10, paddingVertical: 4, marginBottom: 8, flexDirection: 'row', alignItems: 'center', alignSelf: 'flex-start' }}>
                  <Ionicons name="alert-circle" size={13} color="#dc2626" style={{ marginRight: 4 }} />
                  <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 12, color: '#dc2626' }}>Out of stock!</Text>
                </View>
              )}
              <ProductCard
                id={product.id}
                name={product.name}
                price={product.price}
                salePrice={product.salePrice}
                imageUrl={product.imageUrl}
                vendorId={product.vendorId}
                onPress={() => router.push(`/product/${product.id}` as any)}
              />
            </View>
          ))}
        </View>
        <View style={{ height: 40 }} />
      </ScrollView>
    </SafeAreaView>
  );
}

import React from 'react';
import { View, Text, ScrollView, Pressable } from 'react-native';
import { Stack, router } from 'expo-router';
import { Ionicons } from '@expo/vector-icons';
import { useTheme } from '../theme/ThemeContext';
import { useNotificationStore } from '../store/notificationStore';
import { SafeAreaView } from 'react-native-safe-area-context';

export default function NotificationsScreen() {
  const { colors } = useTheme();
  const { notifications, markAsRead, markAllAsRead, clearAll } = useNotificationStore();

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: colors.surfaceSoft }} edges={['top', 'bottom']}>
      <Stack.Screen
        options={{
          headerShown: true,
          title: 'Notifications',
          headerStyle: { backgroundColor: colors.surface },
          headerTintColor: colors.ink,
          headerShadowVisible: false,
          headerLeft: () => (
            <Pressable onPress={() => router.back()} style={{ padding: 8, marginLeft: -8 }}>
              <Ionicons name="arrow-back" size={24} color={colors.ink} />
            </Pressable>
          ),
          headerRight: () => notifications.length > 0 ? (
            <Pressable onPress={markAllAsRead} style={{ padding: 8 }}>
              <Ionicons name="checkmark-done-outline" size={24} color={colors.primary} />
            </Pressable>
          ) : null,
        }}
      />

      <ScrollView contentContainerStyle={{ padding: 16 }}>
        {notifications.length === 0 ? (
          <View style={{ alignItems: 'center', justifyContent: 'center', marginTop: 100 }}>
            <Ionicons name="notifications-off-outline" size={80} color={colors.surfaceMuted} style={{ marginBottom: 16 }} />
            <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 18, color: colors.ink, marginBottom: 8 }}>
              No Notifications Yet
            </Text>
            <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 14, color: colors.inkMuted, textAlign: 'center' }}>
              We'll let you know when there are updates to your orders or special offers.
            </Text>
          </View>
        ) : (
          <View style={{ gap: 12 }}>
            <View style={{ flexDirection: 'row', justifyContent: 'flex-end', marginBottom: 8 }}>
               <Pressable onPress={clearAll}>
                 <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 13, color: colors.inkMuted }}>Clear All</Text>
               </Pressable>
            </View>

            {notifications.map((notif) => (
              <Pressable
                key={notif.id}
                onPress={() => markAsRead(notif.id)}
                style={({ pressed }) => [{
                  backgroundColor: notif.read ? colors.surfaceSoft : colors.surface,
                  padding: 16,
                  borderRadius: 16,
                  borderWidth: 1,
                  borderColor: notif.read ? 'transparent' : colors.primary + '40', // 40 is hex opacity
                  shadowColor: '#000',
                  shadowOffset: { width: 0, height: 2 },
                  shadowOpacity: notif.read ? 0 : (colors.isDark ? 0.3 : 0.05),
                  shadowRadius: 8,
                  elevation: notif.read ? 0 : 2,
                  opacity: pressed ? 0.8 : 1,
                  flexDirection: 'row',
                }]}
              >
                <View style={{ width: 40, height: 40, borderRadius: 20, backgroundColor: notif.read ? colors.surfaceMuted : colors.primary + '20', alignItems: 'center', justifyContent: 'center', marginRight: 16 }}>
                   <Ionicons name="notifications" size={20} color={notif.read ? colors.inkMuted : colors.primary} />
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 15, color: notif.read ? colors.inkSoft : colors.ink, marginBottom: 4 }}>
                    {notif.title}
                  </Text>
                  <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 14, color: colors.inkMuted, lineHeight: 20 }}>
                    {notif.body}
                  </Text>
                  <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 11, color: colors.inkGhost, marginTop: 8 }}>
                    {new Date(notif.createdAt).toLocaleString()}
                  </Text>
                </View>
                {!notif.read && (
                  <View style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: colors.primary, alignSelf: 'center', marginLeft: 8 }} />
                )}
              </Pressable>
            ))}
          </View>
        )}
      </ScrollView>
    </SafeAreaView>
  );
}

import React, { useState, useContext } from 'react';
import { View, Text, ScrollView, Pressable, Modal, Platform, ActivityIndicator, Alert } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { router } from 'expo-router';
import { WebHeader } from '../../components/WebHeader';
import { useTheme } from '../../theme/ThemeContext';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { listMyOrders, deleteMyOrder, Order } from '../../api/orders';
import { getLocalOrders, LocalOrder } from '../../api/localOrders';
import { AuthContext } from '../../context/AuthContext';
import { useWsEvent } from '../../context/WebSocketContext';

// Unified display type that covers both backend and local orders
interface DisplayOrder {
  id: string;
  ref: string;
  status: string;
  subtotal: number;
  shipping_fee: number;
  total_amount: number;
  delivery_pin?: string | null;
  items: { product_id: string; name?: string; quantity: number }[];
  created_at: string;
  isLocal: boolean;
  canDelete: boolean;
}

const DELETABLE_STATUSES = new Set(['delivered', 'cancelled', 'refunded']);

function toDisplayOrder(order: Order): DisplayOrder {
  return {
    id: order.id,
    ref: order.id.slice(-8).toUpperCase(),
    status: order.status,
    subtotal: order.subtotal,
    shipping_fee: order.shipping_fee,
    total_amount: order.total_amount,
    delivery_pin: order.delivery_pin,
    items: order.items.map(i => ({
      product_id: i.product_id,
      name: i.product_name ?? undefined,
      quantity: i.quantity,
    })),
    created_at: order.created_at,
    isLocal: false,
    canDelete: DELETABLE_STATUSES.has(order.status),
  };
}

function localToDisplayOrder(order: LocalOrder): DisplayOrder {
  return {
    id: order.id,
    ref: order.ref,
    status: order.status,
    subtotal: order.subtotal,
    shipping_fee: order.shipping_fee,
    total_amount: order.total_amount,
    items: order.items.map(i => ({ product_id: i.product_id, name: i.name, quantity: i.quantity })),
    created_at: order.created_at,
    isLocal: true,
    canDelete: DELETABLE_STATUSES.has(order.status),
  };
}

function PinModal({
  visible, code, orderId, onClose, colors,
}: {
  visible: boolean; code: string; orderId: string; onClose: () => void; colors: any;
}) {
  const digits = code.split('');
  return (
    <Modal visible={visible} transparent animationType="slide" onRequestClose={onClose}>
      <Pressable
        style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.55)', justifyContent: 'flex-end' }}
        onPress={onClose}
      >
        <Pressable
          onPress={e => e.stopPropagation()}
          style={{
            backgroundColor: colors.surface,
            borderTopLeftRadius: 28, borderTopRightRadius: 28,
            padding: 28, paddingBottom: 44,
          }}
        >
          <View style={{ width: 40, height: 4, borderRadius: 2, backgroundColor: colors.surfaceMuted, alignSelf: 'center', marginBottom: 24 }} />

          <View style={{ alignItems: 'center', marginBottom: 28 }}>
            <View style={{
              width: 64, height: 64, borderRadius: 32,
              backgroundColor: colors.primaryGhost, alignItems: 'center', justifyContent: 'center',
              marginBottom: 16,
            }}>
              <Ionicons name="shield-checkmark" size={34} color={colors.primaryDim} />
            </View>
            <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 22, color: colors.ink, marginBottom: 6 }}>
              Your Delivery PIN
            </Text>
            <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 14, color: colors.inkMuted, textAlign: 'center', lineHeight: 22, maxWidth: 280 }}>
              Give this code to the delivery driver when your order arrives. Do not share it before delivery.
            </Text>
          </View>

          <View style={{
            flexDirection: 'row', gap: 12, justifyContent: 'center',
            backgroundColor: colors.surfaceSoft,
            borderRadius: 20, padding: 24,
            marginBottom: 24,
            borderWidth: 2, borderColor: colors.primaryBorder,
          }}>
            {digits.map((digit, i) => (
              <View key={i} style={{
                width: 56, height: 72, borderRadius: 16,
                backgroundColor: colors.primary, alignItems: 'center', justifyContent: 'center',
                shadowColor: colors.primary, shadowOffset: { width: 0, height: 6 },
                shadowOpacity: 0.35, shadowRadius: 12, elevation: 6,
              }}>
                <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 32, color: '#222022' }}>{digit}</Text>
              </View>
            ))}
          </View>

          <View style={{
            flexDirection: 'row', gap: 10, alignItems: 'flex-start',
            backgroundColor: colors.warningGhost, borderRadius: 14, padding: 14, marginBottom: 24,
          }}>
            <Ionicons name="information-circle" size={18} color={colors.warning} style={{ marginTop: 1 }} />
            <Text style={{ flex: 1, fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.warning, lineHeight: 20 }}>
              For order <Text style={{ fontFamily: 'Inter_700Bold' }}>{orderId}</Text>. This PIN confirms the driver handed the package to you personally.
            </Text>
          </View>

          <Pressable
            onPress={onClose}
            style={({ pressed }) => ({
              backgroundColor: pressed ? colors.primaryDim : colors.primary,
              borderRadius: 16, paddingVertical: 16, alignItems: 'center',
            })}
          >
            <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 16, color: '#222022' }}>Got it, I'm ready</Text>
          </Pressable>
        </Pressable>
      </Pressable>
    </Modal>
  );
}

function formatDate(iso: string) {
  return new Date(iso).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
}

export default function OrdersScreen() {
  const { colors } = useTheme();
  const { token } = useContext(AuthContext);
  const queryClient = useQueryClient();
  const [activePinOrderId, setActivePinOrderId] = useState<string | null>(null);
  const [deletingOrderId, setDeletingOrderId] = useState<string | null>(null);

  // Fetch backend orders (may be empty / fail silently)
  const { data: backendOrders = [], isLoading: backendLoading } = useQuery({
    queryKey: ['my-orders'],
    queryFn: () => listMyOrders(token!),
    enabled: !!token,
    retry: false,
  });

  // Real-time order status updates via WebSocket
  useWsEvent('order_status_changed', () => {
    queryClient.invalidateQueries({ queryKey: ['my-orders'] });
  });

  // Fetch local orders (always available)
  const { data: localOrders = [], isLoading: localLoading } = useQuery({
    queryKey: ['local-orders'],
    queryFn: () => getLocalOrders(),
  });

  const isLoading = backendLoading || localLoading;

  // Delete mutation (backend orders only)
  const deleteMutation = useMutation({
    mutationFn: (orderId: string) => deleteMyOrder(token!, orderId),
    onSuccess: () => {
      setDeletingOrderId(null);
      queryClient.invalidateQueries({ queryKey: ['my-orders'] });
    },
    onError: (err: any) => {
      setDeletingOrderId(null);
      if (Platform.OS === 'web') {
        window.alert(`Could not delete order: ${err.message}`);
      } else {
        Alert.alert('Error', err.message ?? 'Could not delete order.');
      }
    },
  });

  const handleDelete = (order: DisplayOrder) => {
    if (order.isLocal) {
      // Local orders: just remove from AsyncStorage
      import('../../api/localOrders').then(({ removeLocalOrder }) => {
        removeLocalOrder(order.id).then(() => {
          queryClient.invalidateQueries({ queryKey: ['local-orders'] });
        });
      });
      return;
    }
    const confirm = () => {
      setDeletingOrderId(order.id);
      deleteMutation.mutate(order.id);
    };
    if (Platform.OS === 'web') {
      if (window.confirm(`Remove order #${order.ref} from your history? This cannot be undone.`)) confirm();
    } else {
      Alert.alert(
        'Remove Order',
        `Remove order #${order.ref} from your history? This cannot be undone.`,
        [
          { text: 'Cancel', style: 'cancel' },
          { text: 'Remove', style: 'destructive', onPress: confirm },
        ],
      );
    }
  };

  // Merge: live backend orders first, then any offline local orders that aren't on the backend
  const backendOrderIds = new Set(backendOrders.map((o: any) => o.id));
  const uniqueLocalOrders = localOrders.filter((o: any) => !backendOrderIds.has(o.id));

  const allOrders: DisplayOrder[] = [
    ...backendOrders.map(toDisplayOrder),
    ...uniqueLocalOrders.map(localToDisplayOrder),
  ].sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());

  const STATUS_CFG: Record<string, { label: string; bg: string; text: string; icon: any }> = {
    pending:    { label: 'New Order',  bg: colors.surfaceSoft,  text: colors.inkMuted,   icon: 'time-outline' },
    confirmed:  { label: 'Confirmed',  bg: colors.infoGhost,    text: colors.info,       icon: 'checkmark-outline' },
    processing: { label: 'Processing', bg: colors.infoGhost,    text: colors.info,       icon: 'time-outline' },
    shipped:    { label: 'Shipped',    bg: colors.primaryGhost, text: colors.primaryDim, icon: 'car-outline' },
    delivered:  { label: 'Delivered',  bg: colors.successGhost, text: colors.success,    icon: 'checkmark-circle' },
    cancelled:  { label: 'Cancelled',  bg: colors.errorGhost,   text: colors.error,      icon: 'close-circle' },
    refunded:   { label: 'Refunded',   bg: colors.warningGhost, text: colors.warning,    icon: 'return-up-back-outline' },
  };

  const activePinOrder = allOrders.find(o => o.id === activePinOrderId) ?? null;

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: colors.surfaceSoft }} edges={['top']}>
      <WebHeader />

      <View style={{
        flexDirection: 'row', alignItems: 'center',
        paddingHorizontal: 24, paddingVertical: 16,
        backgroundColor: colors.surface,
        borderBottomWidth: 1, borderBottomColor: colors.surfaceMuted,
      }}>
        <Pressable
          onPress={() => router.canGoBack() ? router.back() : router.replace('/(tabs)/profile' as any)}
          style={{ padding: 8, marginRight: 8, marginLeft: -8 }}
        >
          <Ionicons name="arrow-back" size={24} color={colors.ink} />
        </Pressable>
        <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 20, color: colors.ink }}>My Orders</Text>
        {allOrders.length > 0 && (
          <View style={{ marginLeft: 8, backgroundColor: colors.primaryGhost, paddingHorizontal: 8, paddingVertical: 2, borderRadius: 10 }}>
            <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 12, color: colors.primaryDim }}>{allOrders.length}</Text>
          </View>
        )}
      </View>

      {isLoading ? (
        <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
          <ActivityIndicator size="large" color={colors.primary} />
        </View>
      ) : allOrders.length === 0 ? (
        <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', padding: 40 }}>
          <Ionicons name="bag-outline" size={72} color={colors.surfaceMuted} />
          <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 20, color: colors.ink, marginTop: 20 }}>No orders yet</Text>
          <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 14, color: colors.inkMuted, marginTop: 8, textAlign: 'center' }}>
            When you place orders, they'll appear here.
          </Text>
          <Pressable
            onPress={() => router.replace('/(tabs)' as any)}
            style={{ marginTop: 24, paddingHorizontal: 28, paddingVertical: 14, backgroundColor: colors.ink, borderRadius: 24 }}
          >
            <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 15, color: colors.surface }}>Start Shopping</Text>
          </Pressable>
        </View>
      ) : (
        <ScrollView style={{ flex: 1 }} contentContainerStyle={{ padding: 20, gap: 16 }} showsVerticalScrollIndicator={false}>
          {allOrders.map(order => {
            const cfg = STATUS_CFG[order.status] ?? STATUS_CFG.confirmed;
            const needsPin = order.status === 'shipped' && !!order.delivery_pin;
            const isDeleting = deletingOrderId === order.id && deleteMutation.isPending;

            return (
              <View
                key={order.id}
                style={{
                  backgroundColor: colors.surface, borderRadius: 24,
                  borderWidth: 1, borderColor: needsPin ? colors.primaryBorder : colors.surfaceMuted,
                  shadowColor: needsPin ? colors.primary : '#000',
                  shadowOffset: { width: 0, height: needsPin ? 6 : 3 },
                  shadowOpacity: needsPin ? 0.1 : 0.04,
                  shadowRadius: needsPin ? 16 : 10, elevation: 3,
                  overflow: 'hidden',
                  opacity: isDeleting ? 0.5 : 1,
                }}
              >
                {needsPin && <View style={{ height: 3, backgroundColor: colors.primary }} />}

                <View style={{ padding: 20 }}>
                  {/* Order header */}
                  <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 12 }}>
                    <View>
                      <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 16, color: colors.ink }}>#{order.ref}</Text>
                      <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 12, color: colors.inkGhost, marginTop: 2 }}>
                        {formatDate(order.created_at)} · {order.items.length} item{order.items.length !== 1 ? 's' : ''}
                      </Text>
                    </View>
                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
                      <View style={{ backgroundColor: cfg.bg, paddingHorizontal: 12, paddingVertical: 5, borderRadius: 12, flexDirection: 'row', alignItems: 'center', gap: 5 }}>
                        <Ionicons name={cfg.icon} size={13} color={cfg.text} />
                        <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 12, color: cfg.text }}>{cfg.label}</Text>
                      </View>
                      {/* Delete button — only for completed orders */}
                      {order.canDelete && (
                        <Pressable
                          onPress={() => handleDelete(order)}
                          disabled={isDeleting}
                          style={({ pressed }) => ({
                            width: 32, height: 32, borderRadius: 10,
                            backgroundColor: pressed ? colors.errorGhost : colors.surfaceSoft,
                            borderWidth: 1, borderColor: colors.errorGhost,
                            alignItems: 'center', justifyContent: 'center',
                          })}
                          accessibilityLabel="Remove order from history"
                        >
                          {isDeleting
                            ? <ActivityIndicator size="small" color={colors.error} />
                            : <Ionicons name="trash-outline" size={15} color={colors.error} />
                          }
                        </Pressable>
                      )}
                    </View>
                  </View>

                  {/* Items list — show product name */}
                  {order.items.map((item, idx) => (
                    <View key={idx} style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 6 }}>
                      <Ionicons name="cube-outline" size={14} color={colors.inkGhost} style={{ marginRight: 6 }} />
                      <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.inkMuted, flex: 1 }} numberOfLines={1}>
                        {item.name ?? `Product #${item.product_id.slice(0, 8).toUpperCase()}`} × {item.quantity}
                      </Text>
                    </View>
                  ))}

                  {/* Totals */}
                  <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginTop: 10, paddingTop: 12, borderTopWidth: 1, borderTopColor: colors.surfaceMuted, marginBottom: 14 }}>
                    <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.inkMuted }}>
                      Subtotal ${order.subtotal.toFixed(2)} · Shipping ${order.shipping_fee.toFixed(2)}
                    </Text>
                    <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 18, color: colors.ink }}>${order.total_amount.toFixed(2)}</Text>
                  </View>

                  {/* PIN banner for shipped orders */}
                  {needsPin && (
                    <Pressable
                      onPress={() => setActivePinOrderId(order.id)}
                      style={({ pressed }) => ({
                        flexDirection: 'row', alignItems: 'center',
                        backgroundColor: colors.primaryGhost,
                        borderRadius: 14, padding: 14, marginBottom: 12,
                        borderWidth: 1, borderColor: colors.primaryBorder,
                        gap: 12, opacity: pressed ? 0.8 : 1,
                      })}
                    >
                      <View style={{ width: 40, height: 40, borderRadius: 20, backgroundColor: colors.primaryDim, alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                        <Ionicons name="keypad" size={20} color="#ffffff" />
                      </View>
                      <View style={{ flex: 1 }}>
                        <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 14, color: colors.primaryDim }}>Tap to see your Delivery PIN</Text>
                        <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 12, color: colors.primaryDim, marginTop: 2 }}>
                          Show this code to the driver to complete delivery
                        </Text>
                      </View>
                      <Ionicons name="chevron-forward" size={18} color={colors.primaryDim} />
                    </Pressable>
                  )}

                  {/* Delivered badge */}
                  {order.status === 'delivered' && (
                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10, backgroundColor: colors.successGhost, borderRadius: 12, padding: 12, marginBottom: 12 }}>
                      <Ionicons name="checkmark-circle" size={20} color={colors.success} />
                      <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 13, color: colors.success }}>Delivered & confirmed</Text>
                    </View>
                  )}

                  {/* Actions */}
                  <View style={{ flexDirection: 'row', gap: 10 }}>
                    <Pressable
                      onPress={() => router.push(`/order-tracking/${order.id}` as any)}
                      style={({ pressed }) => ({
                        flex: 1, backgroundColor: pressed ? colors.surfaceMuted : colors.surfaceSoft,
                        paddingVertical: 12, borderRadius: 12, alignItems: 'center',
                        borderWidth: 1, borderColor: colors.surfaceMuted,
                      })}
                    >
                      <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 13, color: colors.inkSoft }}>Track Order</Text>
                    </Pressable>
                    <Pressable
                      onPress={() => {
                        if (order.status === 'delivered') {
                          router.push(`/write-review?productId=${order.items[0]?.product_id}` as any);
                        } else {
                          router.push('/profile/support' as any);
                        }
                      }}
                      style={({ pressed }) => ({
                        flex: 1, backgroundColor: pressed ? colors.surfaceMuted : colors.surfaceSoft,
                        paddingVertical: 12, borderRadius: 12, alignItems: 'center',
                        borderWidth: 1, borderColor: colors.surfaceMuted,
                      })}
                    >
                      <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 13, color: colors.inkSoft }}>
                        {order.status === 'delivered' ? 'Leave Review' : 'Help'}
                      </Text>
                    </Pressable>
                  </View>
                </View>
              </View>
            );
          })}
          <View style={{ height: 24 }} />
        </ScrollView>
      )}

      {activePinOrder && (
        <PinModal
          visible={!!activePinOrder}
          code={activePinOrder.delivery_pin ?? '----'}
          orderId={`#${activePinOrder.ref}`}
          onClose={() => setActivePinOrderId(null)}
          colors={colors}
        />
      )}
    </SafeAreaView>
  );
}

