import React, { useState, useEffect, useRef } from 'react';
import {
  View, Text, ScrollView, Pressable, Platform, useWindowDimensions,
  Modal, TextInput, ActivityIndicator
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { router, useLocalSearchParams } from 'expo-router';
import { useTheme } from '../../../theme/ThemeContext';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useAuth } from '../../../context/AuthContext';
import { getVendorOrderDetail } from '../../../api/vendors';
import { useWsEvent } from '../../../context/WebSocketContext';

const STATUSES = ['pending', 'confirmed', 'processing', 'shipped', 'delivered'];
const STATUS_LABELS: Record<string, string> = {
  pending: 'New Order',
  confirmed: 'Confirmed',
  processing: 'Processing',
  shipped: 'Shipped',
  delivered: 'Delivered',
  cancelled: 'Cancelled',
  refunded: 'Refunded',
};

// Real PIN verification happens at the backend

export default function VendorOrderDetailScreen() {
  const { colors } = useTheme();
  const { id } = useLocalSearchParams<{ id: string }>();
  const { width } = useWindowDimensions();
  const isDesktop = width >= 768 && Platform.OS === 'web';
  const { token } = useAuth();
  const queryClient = useQueryClient();

  const orderId = Array.isArray(id) ? id[0] : id;

  // Track in-flight status update requests so we can abort them on unmount
  const abortControllerRef = useRef<AbortController | null>(null);
  useEffect(() => {
    return () => {
      // Cancel any pending status PATCH when the screen is unmounted (e.g. go back)
      abortControllerRef.current?.abort();
    };
  }, []);

  const { data: order, isLoading } = useQuery({
    queryKey: ['vendor-order', orderId],
    queryFn: () => getVendorOrderDetail(token!, orderId!),
    enabled: !!token && !!orderId,
  });

  // Real-time status updates via WebSocket
  useWsEvent('order_status_changed', (event) => {
    if (event.order_id === orderId) {
      queryClient.invalidateQueries({ queryKey: ['vendor-order', orderId] });
      queryClient.invalidateQueries({ queryKey: ['vendor-orders'] });
    }
  });

  const [currentStatus, setCurrentStatus] = useState<string>('pending');
  const [showVerifyModal, setShowVerifyModal] = useState(false);
  const [pinInput, setPinInput] = useState('');
  const [pinError, setPinError] = useState('');
  const [verifySuccess, setVerifySuccess] = useState(false);
  const [statusError, setStatusError] = useState<string | null>(null);
  const [statusSaving, setStatusSaving] = useState(false);

  useEffect(() => {
    if (order?.status) setCurrentStatus(order.status);
  }, [order?.status]);

  if (isLoading || !order) {
    return (
      <SafeAreaView style={{ flex: 1, backgroundColor: colors.surfaceSoft, justifyContent: 'center', alignItems: 'center' }} edges={['top']}>
        <ActivityIndicator size="large" color={colors.primary} />
      </SafeAreaView>
    );
  }

  // No local pin code comparison needed, verify with backend.
  const STATUS_CFG: Record<string, { bg: string; text: string }> = {
    pending: { bg: colors.infoGhost, text: colors.info },
    confirmed: { bg: colors.primaryGhost, text: colors.primaryDim },
    processing: { bg: colors.warningGhost, text: colors.warning },
    shipped: { bg: colors.primaryGhost, text: colors.primaryDim },
    delivered: { bg: colors.successGhost, text: colors.success },
    cancelled: { bg: colors.errorGhost, text: colors.error },
    refunded: { bg: colors.errorGhost, text: colors.error },
  };

  const cfg = STATUS_CFG[currentStatus] || STATUS_CFG.pending;
  const canVerifyDelivery = currentStatus === 'shipped';

  const updateStatus = async (newStatus: string) => {
    if (newStatus === 'delivered') return; // Must go through PIN verification
    if (newStatus === currentStatus) return; // Already at this status — nothing to do
    if (statusSaving) return;

    const previousStatus = currentStatus;
    setCurrentStatus(newStatus); // optimistic update
    setStatusError(null);
    setStatusSaving(true);

    // Create a new AbortController for this request
    const controller = new AbortController();
    abortControllerRef.current = controller;

    try {
      const BASE_URL = process.env.EXPO_PUBLIC_API_BASE_URL ?? 'http://127.0.0.1:8000';
      const res = await fetch(`${BASE_URL}/orders/${order.id}/status`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({ status: newStatus }),
        signal: controller.signal,
      });

      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err?.detail || `Failed to update status (${res.status})`);
      }

      queryClient.invalidateQueries({ queryKey: ['vendor-order', order.id] });
      // Use an exact prefix match so only vendor-orders queries are invalidated
      queryClient.invalidateQueries({ queryKey: ['vendor-orders'], exact: false });
    } catch (e: any) {
      // Ignore abort errors — they happen on normal navigation
      if (e?.name === 'AbortError') return;
      // Revert the optimistic update on failure
      setCurrentStatus(previousStatus);
      setStatusError(e.message || 'Failed to update status. Please try again.');
    } finally {
      setStatusSaving(false);
    }
  };

  const handleVerifyPin = async () => {
    try {
      const BASE_URL = process.env.EXPO_PUBLIC_API_BASE_URL ?? 'http://127.0.0.1:8000';
      const res = await fetch(`${BASE_URL}/orders/${order.id}/verify-delivery`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({ pin: pinInput })
      });
      
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err?.detail || 'Incorrect delivery PIN');
      }

      setVerifySuccess(true);
      setPinError('');
      setCurrentStatus('delivered');
      queryClient.invalidateQueries({ queryKey: ['vendor-orders'] });
      queryClient.invalidateQueries({ queryKey: ['vendor-order', order.id] });

      setTimeout(() => {
        setShowVerifyModal(false);
        setVerifySuccess(false);
        setPinInput('');
      }, 2000);
    } catch (e: any) {
      setPinError(e.message || 'Incorrect delivery PIN');
      setPinInput('');
    }
  };

  const handleCloseModal = () => {
    setShowVerifyModal(false);
    setPinInput('');
    setPinError('');
    setVerifySuccess(false);
  };

  // Calculate order subtotal for ONLY the vendor's items in this order
  const vendorTotal = order.items.reduce((acc: number, item: any) => acc + ((item.discount_price ?? item.unit_price) * item.quantity), 0);

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: colors.surfaceSoft }} edges={['top']}>
      {/* ─── Header ─── */}
      <View style={{
        flexDirection: 'row', alignItems: 'center',
        paddingHorizontal: 20, paddingVertical: 16,
        backgroundColor: colors.surface,
        borderBottomWidth: 1, borderBottomColor: colors.surfaceMuted,
      }}>
        <Pressable
          onPress={() => router.canGoBack() ? router.back() : router.push('/vendor-dashboard/orders' as any)}
          style={{ marginRight: 12, width: 38, height: 38, borderRadius: 19, backgroundColor: colors.surfaceSoft, alignItems: 'center', justifyContent: 'center' }}
        >
          <Ionicons name="arrow-back" size={22} color={colors.ink} />
        </Pressable>
        <View style={{ flex: 1 }}>
          <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 18, color: colors.ink }}>Order #{order.id.slice(-8).toUpperCase()}</Text>
          <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 12, color: colors.inkGhost }}>{new Date(order.created_at).toLocaleString()}</Text>
        </View>
        <View style={{ backgroundColor: cfg.bg, paddingHorizontal: 12, paddingVertical: 5, borderRadius: 12 }}>
          <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 12, color: cfg.text }}>{STATUS_LABELS[currentStatus] || currentStatus}</Text>
        </View>
      </View>

      <ScrollView
        style={{ flex: 1 }}
        contentContainerStyle={{
          padding: 20, gap: 16,
          flexDirection: isDesktop ? 'row' : 'column',
          alignItems: 'flex-start',
        }}
        showsVerticalScrollIndicator={false}
      >
        {/* ─── Left Column ─── */}
        <View style={{ flex: 1, gap: 16, width: isDesktop ? undefined : '100%' }}>

          {/* Delivery Code Banner — visible when out for delivery */}
          {canVerifyDelivery && (
            <View style={{
              borderRadius: 20, overflow: 'hidden',
              backgroundColor: colors.primary,
              padding: 20,
            }}>
              <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 6 }}>
                <Ionicons name="shield-checkmark" size={18} color={colors.ink} style={{ marginRight: 8 }} />
                <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 14, color: colors.ink }}>Delivery Verification Required</Text>
              </View>
              <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.ink, lineHeight: 20, marginBottom: 16 }}>
                When the driver reaches the customer, ask for their 4-digit delivery code to confirm successful delivery.
              </Text>
              <Pressable
                onPress={() => setShowVerifyModal(true)}
                style={({ pressed }) => ({
                  backgroundColor: pressed ? colors.surfaceMuted : colors.surface,
                  borderRadius: 14, paddingVertical: 12, paddingHorizontal: 16,
                  flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 8,
                })}
              >
                <Ionicons name="keypad" size={20} color={colors.ink} />
                <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 15, color: colors.ink }}>Enter Customer PIN</Text>
              </Pressable>
            </View>
          )}

          {/* Delivered confirmation */}
          {currentStatus === 'delivered' && (
            <View style={{
              borderRadius: 20, backgroundColor: '#dcfce7',
              padding: 20, flexDirection: 'row', alignItems: 'center', gap: 14,
            }}>
              <View style={{ width: 48, height: 48, borderRadius: 24, backgroundColor: '#16a34a', alignItems: 'center', justifyContent: 'center' }}>
                <Ionicons name="checkmark-circle" size={28} color="#ffffff" />
              </View>
              <View style={{ flex: 1 }}>
                <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 15, color: '#166534' }}>Delivery Confirmed!</Text>
                <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: '#15803d', marginTop: 2 }}>
                  Customer PIN was verified successfully.
                </Text>
              </View>
            </View>
          )}

          {/* Order Summary / Dispatch Info */}
          <View style={{ backgroundColor: colors.surface, borderRadius: 20, padding: 20, borderWidth: 1, borderColor: colors.surfaceMuted }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 16 }}>
              <Ionicons name="document-text" size={20} color={colors.primary} style={{ marginRight: 8 }} />
              <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 16, color: colors.ink }}>Order Summary / Dispatch Info</Text>
            </View>

            {/* Customer Details */}
            <View style={{ backgroundColor: colors.surfaceSoft, borderRadius: 12, padding: 16, marginBottom: 16 }}>
              <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 13, color: colors.inkGhost, textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: 8 }}>Customer Details</Text>
              
              <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 8 }}>
                <Ionicons name="person-outline" size={16} color={colors.inkMuted} style={{ marginRight: 8 }} />
                <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 15, color: colors.ink }}>{order.shipping_address?.name || 'Customer'}</Text>
              </View>
              
              <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 8 }}>
                <Ionicons name="call-outline" size={16} color={colors.inkMuted} style={{ marginRight: 8 }} />
                <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 15, color: colors.ink }}>
                  {order.shipping_address?.phone || 'No phone number provided'}
                </Text>
              </View>

              <View style={{ flexDirection: 'row', alignItems: 'flex-start', marginBottom: order.shipping_address?.landmark ? 8 : 0 }}>
                <Ionicons name="location-outline" size={16} color={colors.inkMuted} style={{ marginRight: 8, marginTop: 2 }} />
                <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 15, color: colors.ink, flex: 1, lineHeight: 22 }}>
                  {order.shipping_address?.street}{'\n'}{order.shipping_address?.city}
                </Text>
              </View>

              {order.shipping_address?.landmark ? (
                <View style={{ flexDirection: 'row', alignItems: 'flex-start' }}>
                  <Ionicons name="flag-outline" size={16} color={colors.inkMuted} style={{ marginRight: 8, marginTop: 2 }} />
                  <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 14, color: colors.inkMuted, flex: 1 }}>
                    Landmark: {order.shipping_address.landmark}
                  </Text>
                </View>
              ) : null}
            </View>

            {/* Order Items */}
            <View>
              <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 13, color: colors.inkGhost, textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: 12 }}>Items Ordered</Text>
              {order.items.map((item: any) => (
                <View key={item.id} style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 8 }}>
                  <View style={{ flex: 1, marginRight: 8 }}>
                    <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 15, color: colors.ink }}>
                      {item.product_name ?? `Product #${(item.product_id ?? '').slice(0, 8).toUpperCase()}`}
                    </Text>
                    <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.inkGhost, marginTop: 2 }}>
                      Quantity: {item.quantity} {item.color_chosen ? `· Color: ${item.color_chosen}` : ''}
                    </Text>
                  </View>
                  <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 15, color: colors.ink }}>
                    ${((item.discount_price ?? item.unit_price) * item.quantity).toFixed(2)}
                  </Text>
                </View>
              ))}
              <View style={{ height: 1, backgroundColor: colors.surfaceMuted, marginVertical: 12 }} />
              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>
                <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 16, color: colors.ink }}>Total Amount</Text>
                <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 18, color: colors.primaryDim }}>${vendorTotal.toFixed(2)}</Text>
              </View>
            </View>
          </View>
        </View>

        {/* ─── Right Column: Status Update ─── */}
        <View style={{ flex: isDesktop ? 1 : undefined, width: isDesktop ? undefined : '100%', gap: 16 }}>
          <View style={{ backgroundColor: colors.surface, borderRadius: 20, padding: 20, borderWidth: 1, borderColor: colors.surfaceMuted }}>
            <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 16, color: colors.ink, marginBottom: 16 }}>Update Order Status</Text>
            <View style={{ gap: 8 }}>
              {/* Status error banner */}
              {statusError && (
                <View style={{
                  backgroundColor: colors.errorGhost, borderRadius: 12,
                  padding: 12, flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 4,
                }}>
                  <Ionicons name="alert-circle" size={16} color={colors.error} />
                  <Text style={{ flex: 1, fontFamily: 'Inter_600SemiBold', fontSize: 13, color: colors.error }}>
                    {statusError}
                  </Text>
                  <Pressable onPress={() => setStatusError(null)}>
                    <Ionicons name="close" size={16} color={colors.error} />
                  </Pressable>
                </View>
              )}
              {STATUSES.filter(s => s !== 'delivered').map(status => {
                const isCurrent = status === currentStatus;
                const isPast = STATUSES.indexOf(status) < STATUSES.indexOf(currentStatus);
                // Disable if: already at this status, order is delivered, or a save is in progress
                const isDisabled = isCurrent || currentStatus === 'delivered' || statusSaving;
                return (
                  <Pressable
                    key={status}
                    onPress={() => updateStatus(status)}
                    disabled={isDisabled}
                    style={{
                      flexDirection: 'row', alignItems: 'center', padding: 14, borderRadius: 14,
                      backgroundColor: isCurrent ? colors.ink : colors.surfaceSoft,
                      borderWidth: 1.5, borderColor: isCurrent ? colors.ink : colors.surfaceMuted,
                      opacity: isDisabled && !isCurrent ? 0.5 : 1,
                    }}
                  >
                    <View style={{
                      width: 22, height: 22, borderRadius: 11,
                      borderWidth: 2,
                      borderColor: isCurrent ? colors.primary : (isPast ? colors.ink : colors.surfaceMuted),
                      alignItems: 'center', justifyContent: 'center', marginRight: 12,
                    }}>
                      {(isCurrent || isPast) && (
                        <View style={{ width: 10, height: 10, borderRadius: 5, backgroundColor: isCurrent ? colors.primary : colors.ink }} />
                      )}
                    </View>
                    <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 14, color: isCurrent ? colors.surface : (isPast ? colors.ink : colors.inkGhost) }}>
                      {STATUS_LABELS[status]}
                    </Text>
                  </Pressable>
                );
              })}

              {/* Delivered row — only via PIN */}
              <View style={{
                flexDirection: 'row', alignItems: 'center', padding: 14, borderRadius: 14,
                backgroundColor: currentStatus === 'delivered' ? '#dcfce7' : colors.surfaceSoft,
                borderWidth: 1.5, borderColor: currentStatus === 'delivered' ? '#16a34a' : colors.surfaceMuted,
              }}>
                <View style={{
                  width: 22, height: 22, borderRadius: 11, borderWidth: 2,
                  borderColor: currentStatus === 'delivered' ? '#16a34a' : colors.surfaceMuted,
                  alignItems: 'center', justifyContent: 'center', marginRight: 12,
                }}>
                  {currentStatus === 'delivered' && (
                    <Ionicons name="checkmark" size={13} color="#16a34a" />
                  )}
                </View>
                <Text style={{ flex: 1, fontFamily: 'Inter_600SemiBold', fontSize: 14, color: currentStatus === 'delivered' ? '#166534' : colors.inkGhost }}>
                  Delivered
                </Text>
                <View style={{ backgroundColor: colors.warningGhost, paddingHorizontal: 8, paddingVertical: 3, borderRadius: 8 }}>
                  <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 10, color: colors.warning }}>PIN REQUIRED</Text>
                </View>
              </View>
            </View>
          </View>

          {canVerifyDelivery && (
            <Pressable
              onPress={() => setShowVerifyModal(true)}
              style={({ pressed }) => ({
                backgroundColor: pressed ? colors.primaryDim : colors.primary,
                borderRadius: 16, paddingVertical: 16, paddingHorizontal: 20,
                flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 8,
              })}
            >
              <Ionicons name="checkmark-circle" size={20} color={colors.ink} />
              <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 15, color: colors.ink }}>Verify Delivery with PIN</Text>
            </Pressable>
          )}

          <Pressable
            onPress={async () => {
              // Wait for any in-flight status update to finish before navigating away
              if (router.canGoBack()) router.back();
              else router.push('/vendor-dashboard/orders' as any);
            }}
            style={{ backgroundColor: colors.surfaceSoft, borderRadius: 16, paddingVertical: 14, alignItems: 'center', borderWidth: 1, borderColor: colors.surfaceMuted }}
          >
            <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 15, color: colors.inkSoft }}>
              {statusSaving ? 'Saving…' : 'Go Back'}
            </Text>
          </Pressable>
        </View>
      </ScrollView>

      {/* ─── PIN Verify Modal ─── */}
      <Modal
        visible={showVerifyModal}
        transparent
        animationType="slide"
        onRequestClose={handleCloseModal}
      >
        <Pressable
          style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.5)', justifyContent: 'flex-end' }}
          onPress={handleCloseModal}
        >
          <Pressable
            onPress={e => e.stopPropagation()}
            style={{
              backgroundColor: colors.surface,
              borderTopLeftRadius: 28, borderTopRightRadius: 28,
              padding: 28,
              paddingBottom: 40,
            }}
          >
            {verifySuccess ? (
              <View style={{ alignItems: 'center', paddingVertical: 20 }}>
                <View style={{ width: 80, height: 80, borderRadius: 40, backgroundColor: '#dcfce7', alignItems: 'center', justifyContent: 'center', marginBottom: 16 }}>
                  <Ionicons name="checkmark-circle" size={48} color="#16a34a" />
                </View>
                <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 22, color: colors.ink, marginBottom: 8 }}>Delivery Confirmed!</Text>
                <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 14, color: colors.inkMuted, textAlign: 'center' }}>
                  The order has been marked as delivered.
                </Text>
              </View>
            ) : (
              <>
                {/* Handle */}
                <View style={{ width: 40, height: 4, borderRadius: 2, backgroundColor: colors.surfaceMuted, alignSelf: 'center', marginBottom: 24 }} />

                <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 8 }}>
                  <View style={{ width: 44, height: 44, borderRadius: 22, backgroundColor: colors.primaryGhost, alignItems: 'center', justifyContent: 'center', marginRight: 14 }}>
                    <Ionicons name="shield-checkmark" size={22} color={colors.primaryDim} />
                  </View>
                  <View>
                    <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 20, color: colors.ink }}>Enter Delivery PIN</Text>
                    <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.inkMuted }}>Ask the customer for their code</Text>
                  </View>
                </View>

                <View style={{ height: 1, backgroundColor: colors.surfaceMuted, marginVertical: 20 }} />

                <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 14, color: colors.ink, marginBottom: 12 }}>
                  4-Digit Delivery Code
                </Text>

                {/* PIN Input */}
                <TextInput
                  value={pinInput}
                  onChangeText={text => {
                    setPinError('');
                    if (text.length <= 4 && /^\d*$/.test(text)) setPinInput(text);
                  }}
                  placeholder="· · · ·"
                  placeholderTextColor={colors.inkGhost}
                  keyboardType="number-pad"
                  maxLength={4}
                  secureTextEntry={false}
                  style={{
                    backgroundColor: colors.surfaceSoft,
                    borderRadius: 16, borderWidth: 2,
                    borderColor: pinError ? colors.error : pinInput.length === 4 ? colors.primary : colors.surfaceMuted,
                    paddingHorizontal: 24, paddingVertical: 20,
                    fontFamily: 'Inter_700Bold', fontSize: 36,
                    color: colors.ink, textAlign: 'center',
                    letterSpacing: 16,
                    marginBottom: 8,
                    ...(Platform.OS === 'web' ? { outlineStyle: 'none' } as any : {}),
                  }}
                />

                {pinError ? (
                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, marginBottom: 16 }}>
                    <Ionicons name="alert-circle" size={16} color="#dc2626" />
                    <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 13, color: '#dc2626', flex: 1 }}>{pinError}</Text>
                  </View>
                ) : (
                  <View style={{ height: 16 }} />
                )}

                <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 12, color: colors.inkGhost, textAlign: 'center', marginBottom: 20 }}>
                  The customer received this code after payment. Both parties must agree before confirming delivery.
                </Text>

                <Pressable
                  onPress={handleVerifyPin}
                  disabled={pinInput.length < 4}
                  style={({ pressed }) => ({
                    backgroundColor: pinInput.length < 4 ? colors.surfaceMuted : (pressed ? colors.primaryDim : colors.primary),
                    borderRadius: 16, paddingVertical: 16,
                    alignItems: 'center',
                  })}
                >
                  <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 16, color: pinInput.length < 4 ? colors.inkGhost : colors.ink }}>
                    Confirm Delivery
                  </Text>
                </Pressable>

                <Pressable onPress={handleCloseModal} style={{ paddingVertical: 14, alignItems: 'center', marginTop: 8 }}>
                  <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 14, color: colors.inkSoft }}>Cancel</Text>
                </Pressable>
              </>
            )}
          </Pressable>
        </Pressable>
      </Modal>
    </SafeAreaView>
  );
}

import React, { useState, useEffect } from 'react';
import { View, Text, ScrollView, Pressable, Platform, useWindowDimensions, ActivityIndicator } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { router } from 'expo-router';
import { useTheme } from '../../theme/ThemeContext';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { getVendorOrders } from '../../api/vendors';
import { useAuth } from '../../context/AuthContext';
import { useWsEvent } from '../../context/WebSocketContext';

// Match exactly with backend OrderStatusEnum values
const FILTERS = ['All', 'New Order', 'Confirmed', 'Processing', 'Shipped', 'Delivered', 'Cancelled', 'Refunded'];

const FILTER_TO_STATUS: Record<string, string> = {
  'New Order': 'pending',
  'Confirmed': 'confirmed',
  'Processing': 'processing',
  'Shipped': 'shipped',
  'Delivered': 'delivered',
  'Cancelled': 'cancelled',
  'Refunded': 'refunded',
};

export default function VendorOrdersScreen() {
  const { colors } = useTheme();
  const { width } = useWindowDimensions();
  const isDesktop = width >= 768 && Platform.OS === 'web';
  const [filter, setFilter] = useState('All');
  const { token, vendor } = useAuth();
  const queryClient = useQueryClient();

  const { data: orders = [], isLoading, error } = useQuery({
    queryKey: ['vendor-orders', vendor?.id],
    queryFn: () => getVendorOrders(token!, vendor!.id),
    enabled: !!token && !!vendor?.id,
    staleTime: 10_000,
  });

  // Live updates via WebSocket — invalidate on new order or status change
  useWsEvent('new_order', () => {
    queryClient.invalidateQueries({ queryKey: ['vendor-orders', vendor?.id] });
  });
  useWsEvent('order_status_changed', () => {
    queryClient.invalidateQueries({ queryKey: ['vendor-orders', vendor?.id] });
  });

  const STATUS_CFG: Record<string, { label: string; bg: string; text: string; icon: string }> = {
    pending:    { label: 'New Order',  bg: colors.infoGhost,    text: colors.info,       icon: 'time-outline' },
    confirmed:  { label: 'Confirmed',  bg: colors.primaryGhost, text: colors.primaryDim, icon: 'checkmark-circle-outline' },
    processing: { label: 'Processing', bg: colors.warningGhost, text: colors.warning,    icon: 'construct-outline' },
    shipped:    { label: 'Shipped',    bg: colors.primaryGhost, text: colors.primaryDim, icon: 'car-outline' },
    delivered:  { label: 'Delivered',  bg: colors.successGhost, text: colors.success,    icon: 'checkmark-circle' },
    cancelled:  { label: 'Cancelled',  bg: colors.errorGhost,   text: colors.error,      icon: 'close-circle' },
    refunded:   { label: 'Refunded',   bg: colors.warningGhost, text: colors.warning,    icon: 'return-up-back-outline' },
  };

  const filtered = filter === 'All'
    ? orders
    : orders.filter(o => o.status === FILTER_TO_STATUS[filter]);

  return (
    <View style={{ flex: 1, backgroundColor: colors.surfaceSoft }}>
      <View style={{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: 20, paddingVertical: 16, backgroundColor: colors.surface, borderBottomWidth: 1, borderBottomColor: colors.surfaceMuted }}>
        {!isDesktop && (
          <Pressable onPress={() => router.push('/vendor-dashboard' as any)} style={{ marginRight: 12, padding: 4 }}>
            <Ionicons name="arrow-back" size={24} color={colors.ink} />
          </Pressable>
        )}
        <Text style={{ flex: 1, fontFamily: 'Inter_700Bold', fontSize: 20, color: colors.ink }}>Order Management</Text>
        {/* Live indicator dot */}
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 5, backgroundColor: colors.successGhost, paddingHorizontal: 10, paddingVertical: 4, borderRadius: 10 }}>
          <View style={{ width: 6, height: 6, borderRadius: 3, backgroundColor: colors.success }} />
          <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 11, color: colors.success }}>Live</Text>
        </View>
      </View>

      {/* Filter Tabs */}
      <View style={{ borderBottomWidth: 1, borderBottomColor: colors.surfaceMuted, backgroundColor: colors.surfaceSoft }}>
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          style={{ flexGrow: 0 }}
          contentContainerStyle={{
            paddingHorizontal: isDesktop ? 24 : 16,
            paddingVertical: 16,
            gap: 12
          }}
        >
          {FILTERS.map(f => (
            <Pressable
              key={f}
              onPress={() => setFilter(f)}
              style={({ pressed }) => ({
                paddingHorizontal: 20,
                paddingVertical: 10,
                borderRadius: 24,
                backgroundColor: filter === f ? colors.ink : (pressed ? colors.surfaceMuted : colors.surface),
                borderWidth: 1,
                borderColor: filter === f ? colors.ink : colors.surfaceMuted,
                shadowColor: '#000',
                shadowOffset: { width: 0, height: filter === f ? 4 : 1 },
                shadowOpacity: filter === f ? (colors.isDark ? 0.3 : 0.15) : 0.05,
                shadowRadius: filter === f ? 8 : 2,
                elevation: filter === f ? 4 : 1,
              })}
            >
              <Text style={{
                fontFamily: filter === f ? 'Inter_700Bold' : 'Inter_600SemiBold',
                fontSize: 14,
                color: filter === f ? colors.surface : colors.inkSoft
              }}>
                {f}
              </Text>
            </Pressable>
          ))}
        </ScrollView>
      </View>

      <ScrollView style={{ flex: 1 }} contentContainerStyle={{ padding: isDesktop ? 24 : 16, paddingBottom: 60, gap: 16 }}>
        {isLoading ? (
          <ActivityIndicator size="large" color={colors.primary} style={{ marginTop: 40 }} />
        ) : error ? (
          <View style={{ alignItems: 'center', marginTop: 40, padding: 24, backgroundColor: colors.surface, borderRadius: 20, borderWidth: 1, borderColor: colors.errorGhost, marginHorizontal: 4 }}>
            <Ionicons name="alert-circle-outline" size={48} color={colors.error} style={{ marginBottom: 12 }} />
            <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 16, color: colors.ink, marginBottom: 6 }}>Couldn't Load Orders</Text>
            <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.inkMuted, textAlign: 'center', marginBottom: 20 }}>
              {(error as any)?.message ?? 'Something went wrong. Please try again.'}
            </Text>
            <Pressable
              onPress={() => queryClient.invalidateQueries({ queryKey: ['vendor-orders'] })}
              style={({ pressed }) => ({
                backgroundColor: pressed ? colors.surfaceMuted : colors.ink,
                paddingHorizontal: 24, paddingVertical: 12, borderRadius: 16,
              })}
            >
              <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 14, color: colors.surface }}>Retry</Text>
            </Pressable>
          </View>
        ) : filtered.length === 0 ? (
          <View style={{ alignItems: 'center', marginTop: 40 }}>
            <Ionicons name="cube-outline" size={48} color={colors.surfaceMuted} style={{ marginBottom: 16 }} />
            <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 16, color: colors.inkMuted }}>
              {filter === 'All' ? 'No orders yet' : `No ${filter.toLowerCase()} orders`}
            </Text>
          </View>
        ) : (
          filtered.map(order => {
            const cfg = STATUS_CFG[order.status] || { label: order.status, bg: colors.surfaceMuted, text: colors.ink, icon: 'ellipse-outline' };
            const date = new Date(order.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
            return (
              <Pressable
                key={order.id}
                onPress={() => router.push(`/vendor-dashboard/order/${order.id}` as any)}
                style={{ backgroundColor: colors.surface, borderRadius: 18, padding: 16, borderWidth: 1, borderColor: colors.surfaceMuted, shadowColor: '#000', shadowOffset: { width: 0, height: 2 }, shadowOpacity: colors.isDark ? 0.2 : 0.04, shadowRadius: 8, elevation: 2 }}
              >
                <View style={{ flexDirection: 'row', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: 10 }}>
                  <View>
                    <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 15, color: colors.ink }}>#{order.id.slice(-8).toUpperCase()}</Text>
                    <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 12, color: colors.inkGhost, marginTop: 2 }}>{date}</Text>
                  </View>
                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: 5, backgroundColor: cfg.bg, paddingHorizontal: 12, paddingVertical: 5, borderRadius: 12 }}>
                    <Ionicons name={cfg.icon as any} size={12} color={cfg.text} />
                    <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 12, color: cfg.text }}>{cfg.label}</Text>
                  </View>
                </View>
                <View style={{ height: 1, backgroundColor: colors.surfaceMuted, marginBottom: 10 }} />
                <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>
                  <View>
                    <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 14, color: colors.ink }}>{order.customer_name}</Text>
                    <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 12, color: colors.inkMuted, marginTop: 2 }}>{order.items_count} item{order.items_count > 1 ? 's' : ''}</Text>
                  </View>
                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12 }}>
                    <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 16, color: colors.ink }}>${order.total_amount.toFixed(2)}</Text>
                    <Ionicons name="chevron-forward" size={18} color={colors.inkGhost} />
                  </View>
                </View>
              </Pressable>
            );
          })
        )}
      </ScrollView>
    </View>
  );
}

import React, { useState, useEffect } from 'react';
import { View, Text, ScrollView, Pressable, TextInput, Platform, useWindowDimensions, ActivityIndicator } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { router } from 'expo-router';
import { useTheme } from '../../../theme/ThemeContext';
import { Button } from '../../../components/Button';
import { useAuth } from '../../../context/AuthContext';
import { useToast } from '../../../context/ToastContext';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { getVendorMe, updateVendor } from '../../../api/vendors';

function Field({ label, placeholder, value, onChangeText, colors, editable = true }: any) {
  const [focused, setFocused] = useState(false);
  return (
    <View style={{ marginBottom: 18 }}>
      <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 14, color: colors.ink, marginBottom: 8 }}>{label}</Text>
      <TextInput
        value={value}
        onChangeText={onChangeText}
        placeholder={placeholder}
        placeholderTextColor={colors.inkGhost}
        editable={editable}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        style={{
          backgroundColor: editable ? colors.surfaceSoft : colors.surfaceMuted,
          borderRadius: 14,
          paddingHorizontal: 16,
          height: 52,
          fontFamily: 'OpenSans_400Regular',
          fontSize: 15,
          color: editable ? colors.ink : colors.inkGhost,
          borderWidth: 1.5,
          borderColor: focused ? colors.ink : colors.surfaceMuted,
          ...(Platform.OS === 'web' ? { outlineStyle: 'none' } as any : {}),
        }}
      />
    </View>
  );
}

const OPERATING_HOURS = ['Mon–Fri', 'Mon–Sat', 'Mon–Sun', 'Weekends Only'];

export default function BusinessSettingsScreen() {
  const { colors } = useTheme();
  const { width } = useWindowDimensions();
  const isDesktop = width >= 768 && Platform.OS === 'web';
  const { token } = useAuth();
  const { showToast } = useToast();
  const queryClient = useQueryClient();

  const [form, setForm] = useState({
    phone: '',
    email: '',
    address: '',
    hours: 'Mon–Fri',
  });

  const { data: vendor, isLoading } = useQuery({
    queryKey: ['vendor-me'],
    queryFn: () => getVendorMe(token!),
    enabled: !!token,
  });

  // Pre-populate from vendor data once loaded
  useEffect(() => {
    if (vendor) {
      setForm(f => ({
        ...f,
        // Use bio-extracted contact info if we stored it there, else use store_name as fallback
        phone: (vendor as any).contact_phone ?? '',
        email: (vendor as any).contact_email ?? '',
        address: (vendor as any).store_address ?? '',
      }));
    }
  }, [vendor]);

  const mutation = useMutation({
    mutationFn: () =>
      updateVendor(token!, vendor!.id, {
        // Store contact fields in extra metadata — backend will need to support these
        ...(form.phone && { contact_phone: form.phone } as any),
        ...(form.email && { contact_email: form.email } as any),
        ...(form.address && { store_address: form.address } as any),
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['vendor-me'] });
      showToast('Business details saved!', 'success');
    },
    onError: (error: any) => {
      showToast(`Failed to save: ${error.message}`, 'error');
    },
  });

  return (
    <View style={{ flex: 1, backgroundColor: colors.surfaceSoft }}>
      <View style={{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: 20, paddingVertical: 16, backgroundColor: colors.surface, borderBottomWidth: 1, borderBottomColor: colors.surfaceMuted }}>
        <Pressable onPress={() => router.back()} style={{ marginRight: 12, padding: 4 }}>
          <Ionicons name="arrow-back" size={24} color={colors.ink} />
        </Pressable>
        <Text style={{ flex: 1, fontFamily: 'Inter_700Bold', fontSize: 20, color: colors.ink }}>Business Details</Text>
      </View>

      {isLoading ? (
        <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
          <ActivityIndicator size="large" color={colors.primary} />
        </View>
      ) : (
        <ScrollView style={{ flex: 1 }} contentContainerStyle={{ padding: 20, maxWidth: isDesktop ? 640 : undefined, alignSelf: 'center', width: '100%', gap: 4, paddingBottom: 60 }}>

          {/* Locked legal section */}
          <View style={{ backgroundColor: colors.surface, borderRadius: 20, padding: 20, borderWidth: 1, borderColor: colors.surfaceMuted, marginBottom: 16 }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 12 }}>
              <Ionicons name="lock-closed" size={18} color={colors.inkGhost} style={{ marginRight: 8 }} />
              <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 14, color: colors.ink }}>Verified Legal Details</Text>
            </View>
            <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.inkMuted, lineHeight: 20 }}>
              Your TIN and Business Registration Number are locked after verification. Contact support to update these.
            </Text>
          </View>

          <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 17, color: colors.ink, marginBottom: 14, marginTop: 8 }}>Store Name</Text>
          <Field label="Store Name" placeholder="Your store name" value={vendor?.store_name ?? ''} onChangeText={() => {}} colors={colors} editable={false} />

          <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 17, color: colors.ink, marginBottom: 14, marginTop: 8 }}>Contact & Location</Text>
          <Field label="Contact Phone" placeholder="+233 55 000 1234" value={form.phone} onChangeText={(v: string) => setForm(f => ({ ...f, phone: v }))} colors={colors} />
          <Field label="Contact Email" placeholder="hello@yourstore.com" value={form.email} onChangeText={(v: string) => setForm(f => ({ ...f, email: v }))} colors={colors} />
          <Field label="Store Address" placeholder="Physical address" value={form.address} onChangeText={(v: string) => setForm(f => ({ ...f, address: v }))} colors={colors} />

          <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 17, color: colors.ink, marginBottom: 14, marginTop: 8 }}>Operating Hours</Text>
          <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8, marginBottom: 24 }}>
            {OPERATING_HOURS.map(h => (
              <Pressable
                key={h}
                onPress={() => setForm(f => ({ ...f, hours: h }))}
                style={{ paddingHorizontal: 16, paddingVertical: 9, borderRadius: 20, backgroundColor: form.hours === h ? colors.ink : colors.surfaceSoft, borderWidth: 1.5, borderColor: form.hours === h ? colors.ink : colors.surfaceMuted }}
              >
                <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 13, color: form.hours === h ? colors.surface : colors.inkSoft }}>{h}</Text>
              </Pressable>
            ))}
          </View>

          <Button
            title={mutation.isPending ? 'Saving...' : 'Save Changes'}
            onPress={() => mutation.mutate()}
            disabled={mutation.isPending}
          />
        </ScrollView>
      )}
    </View>
  );
}

import React, { useState, useEffect } from 'react';
import { View, Text, ScrollView, Pressable, TextInput, Platform, useWindowDimensions, ActivityIndicator, Image, Alert } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { router } from 'expo-router';
import { useTheme } from '../../../theme/ThemeContext';
import { Button } from '../../../components/Button';
import { useAuth } from '../../../context/AuthContext';
import { useToast } from '../../../context/ToastContext';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { getVendorMe, updateVendor, deleteVendor } from '../../../api/vendors';
import * as ImagePicker from 'expo-image-picker';
import * as Location from 'expo-location';

function Field({ label, placeholder, value, onChangeText, colors, multiline = false }: any) {
  const [focused, setFocused] = useState(false);
  return (
    <View style={{ marginBottom: 18 }}>
      <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 14, color: colors.ink, marginBottom: 8 }}>{label}</Text>
      <TextInput
        value={value}
        onChangeText={onChangeText}
        placeholder={placeholder}
        placeholderTextColor={colors.inkGhost}
        multiline={multiline}
        numberOfLines={multiline ? 4 : 1}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        style={{
          backgroundColor: colors.surfaceSoft,
          borderRadius: 14,
          paddingHorizontal: 16,
          paddingVertical: multiline ? 14 : 0,
          height: multiline ? 110 : 52,
          fontFamily: 'OpenSans_400Regular',
          fontSize: 15,
          color: colors.ink,
          borderWidth: 1.5,
          borderColor: focused ? colors.ink : colors.surfaceMuted,
          textAlignVertical: multiline ? 'top' : 'center',
          ...(Platform.OS === 'web' ? { outlineStyle: 'none' } as any : {}),
        }}
      />
    </View>
  );
}

export default function GeneralSettingsScreen() {
  const { colors } = useTheme();
  const { width } = useWindowDimensions();
  const isDesktop = width >= 768 && Platform.OS === 'web';
  const { token, refreshVendor } = useAuth();
  const { showToast } = useToast();
  const queryClient = useQueryClient();
  const [saved, setSaved] = useState(false);
  const [isLocating, setIsLocating] = useState(false);
  const [form, setForm] = useState({ 
    storeName: '', storeSlug: '', bio: '', 
    logoUrl: '', bannerUrl: '',
    latitude: null as number | null, 
    longitude: null as number | null 
  });

  const { data: vendor, isLoading } = useQuery({
    queryKey: ['vendor-me'],
    queryFn: () => getVendorMe(token!),
    enabled: !!token,
  });

  // Pre-populate form once vendor data loads
  useEffect(() => {
    if (vendor) {
      setForm({
        storeName: vendor.store_name,
        storeSlug: vendor.store_slug,
        bio: vendor.bio ?? '',
        logoUrl: vendor.logo_url ?? '',
        bannerUrl: vendor.banner_url ?? '',
        latitude: vendor.latitude ?? null,
        longitude: vendor.longitude ?? null,
      });
    }
  }, [vendor]);

  const mutation = useMutation({
    mutationFn: () =>
      updateVendor(token!, vendor!.id, {
        store_name: form.storeName,
        store_slug: form.storeSlug,
        bio: form.bio,
        ...(form.logoUrl && { logo_url: form.logoUrl }),
        ...(form.bannerUrl && { banner_url: form.bannerUrl }),
        ...(form.latitude !== null && { latitude: form.latitude }),
        ...(form.longitude !== null && { longitude: form.longitude }),
      }),
    onSuccess: () => {
      setSaved(true);
      queryClient.invalidateQueries({ queryKey: ['vendor-me'] });
      showToast('Store details saved successfully!', 'success');
      setTimeout(() => setSaved(false), 3000);
    },
    onError: (error: any) => {
      showToast(`Failed to save: ${error.message}`, 'error');
    },
  });

  const deleteMutation = useMutation({
    mutationFn: () => deleteVendor(token!, vendor!.id),
    onSuccess: async () => {
      await refreshVendor(); // Remove vendor status from context
      queryClient.invalidateQueries({ queryKey: ['vendor-me'] });
      showToast('Store deleted successfully.', 'success');
      router.replace('/(tabs)');
    },
    onError: (error: any) => {
      showToast(`Failed to delete store: ${error.message}`, 'error');
    }
  });

  const handleDelete = () => {
    if (Platform.OS === 'web') {
      if (window.confirm('Are you sure you want to delete your store? This action cannot be undone and will delete all your products.')) {
        deleteMutation.mutate();
      }
    } else {
      Alert.alert(
        'Delete Store',
        'Are you sure you want to delete your store? This action cannot be undone and will delete all your products.',
        [
          { text: 'Cancel', style: 'cancel' },
          { text: 'Delete', style: 'destructive', onPress: () => deleteMutation.mutate() }
        ]
      );
    }
  };

  const pickImage = async (field: 'logoUrl' | 'bannerUrl') => {
    let result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
      allowsEditing: true,
      aspect: field === 'logoUrl' ? [1, 1] : [3, 1],
      quality: 0.8,
    });

    if (!result.canceled) {
      setForm(prev => ({ ...prev, [field]: result.assets[0].uri }));
    }
  };

  const fetchLocation = async () => {
    setIsLocating(true);
    try {
      let { status } = await Location.requestForegroundPermissionsAsync();
      if (status !== 'granted') {
        showToast('Permission to access location was denied', 'error');
        setIsLocating(false);
        return;
      }

      let location = await Location.getCurrentPositionAsync({ accuracy: Location.Accuracy.High });
      setForm(prev => ({ 
        ...prev, 
        latitude: location.coords.latitude, 
        longitude: location.coords.longitude 
      }));
      showToast('Location updated!', 'success');
    } catch (error) {
      showToast('Failed to fetch location. Please try again.', 'error');
    } finally {
      setIsLocating(false);
    }
  };

  return (
    <View style={{ flex: 1, backgroundColor: colors.surfaceSoft }}>
      <View style={{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: 20, paddingVertical: 16, backgroundColor: colors.surface, borderBottomWidth: 1, borderBottomColor: colors.surfaceMuted }}>
        <Pressable onPress={() => router.back()} style={{ marginRight: 12, padding: 4 }}>
          <Ionicons name="arrow-back" size={24} color={colors.ink} />
        </Pressable>
        <Text style={{ flex: 1, fontFamily: 'Inter_700Bold', fontSize: 20, color: colors.ink }}>General Information</Text>
        {saved && (
          <View style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: '#f0fdf4', paddingHorizontal: 12, paddingVertical: 5, borderRadius: 12 }}>
            <Ionicons name="checkmark-circle" size={15} color="#15803d" style={{ marginRight: 4 }} />
            <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 12, color: '#15803d' }}>Saved</Text>
          </View>
        )}
      </View>

      {isLoading ? (
        <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
          <ActivityIndicator size="large" color={colors.primary} />
        </View>
      ) : (
        <ScrollView style={{ flex: 1 }} contentContainerStyle={{ padding: 20, maxWidth: isDesktop ? 640 : undefined, alignSelf: 'center', width: '100%', gap: 4, paddingBottom: 60 }}>

          <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 17, color: colors.ink, marginBottom: 14 }}>Brand Assets</Text>
          <View style={{ flexDirection: 'row', gap: 14, marginBottom: 24 }}>
            <Pressable onPress={() => pickImage('logoUrl')} style={{ width: 100, height: 100, borderRadius: 20, backgroundColor: colors.primaryGhost, alignItems: 'center', justifyContent: 'center', borderWidth: 1.5, borderStyle: 'dashed', borderColor: colors.primary, overflow: 'hidden' }}>
              {form.logoUrl ? (
                <Image source={{ uri: form.logoUrl }} style={{ width: '100%', height: '100%', resizeMode: 'cover' }} />
              ) : (
                <>
                  <Ionicons name="image-outline" size={28} color={colors.primaryDim} />
                  <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 11, color: colors.primaryDim, marginTop: 6 }}>Logo</Text>
                </>
              )}
            </Pressable>
            <Pressable onPress={() => pickImage('bannerUrl')} style={{ flex: 1, height: 100, borderRadius: 20, backgroundColor: colors.surfaceSoft, alignItems: 'center', justifyContent: 'center', borderWidth: 1.5, borderStyle: 'dashed', borderColor: colors.surfaceMuted, overflow: 'hidden' }}>
               {form.bannerUrl ? (
                <Image source={{ uri: form.bannerUrl }} style={{ width: '100%', height: '100%', resizeMode: 'cover' }} />
              ) : (
                <>
                  <Ionicons name="image-outline" size={28} color={colors.inkGhost} />
                  <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 11, color: colors.inkGhost, marginTop: 6 }}>Banner Image</Text>
                </>
              )}
            </Pressable>
          </View>

          <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 17, color: colors.ink, marginBottom: 14 }}>Store Details</Text>
          <Field label="Store Name" placeholder="Your store name" value={form.storeName} onChangeText={(v: string) => setForm(f => ({ ...f, storeName: v }))} colors={colors} />
          <Field label="Store URL Slug" placeholder="your-store" value={form.storeSlug} onChangeText={(v: string) => setForm(f => ({ ...f, storeSlug: v }))} colors={colors} />
          <View style={{ backgroundColor: colors.surfaceSoft, borderRadius: 12, padding: 14, marginBottom: 18 }}>
            <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.inkMuted }}>
              Your store URL: <Text style={{ color: colors.primaryDim, fontFamily: 'Inter_600SemiBold' }}>electric.app/vendor/{form.storeSlug}</Text>
            </Text>
          </View>
          <Field label="Store Bio" placeholder="Tell customers about your store..." value={form.bio} onChangeText={(v: string) => setForm(f => ({ ...f, bio: v }))} colors={colors} multiline />

          <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 17, color: colors.ink, marginBottom: 14, marginTop: 12 }}>Store Location (GPS)</Text>
          <View style={{ backgroundColor: colors.surface, borderRadius: 14, borderWidth: 1, borderColor: colors.surfaceMuted, padding: 16, marginBottom: 24 }}>
            {form.latitude && form.longitude ? (
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12 }}>
                <Ionicons name="location" size={24} color={colors.success} />
                <View style={{ flex: 1 }}>
                  <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 14, color: colors.ink }}>Location Set</Text>
                  <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 12, color: colors.inkMuted }}>Lat: {form.latitude.toFixed(4)}, Lng: {form.longitude.toFixed(4)}</Text>
                </View>
                <Pressable onPress={fetchLocation} style={{ padding: 8 }}>
                  {isLocating ? <ActivityIndicator size="small" color={colors.primaryDim} /> : <Ionicons name="refresh" size={20} color={colors.primaryDim} />}
                </Pressable>
              </View>
            ) : (
              <Pressable onPress={fetchLocation} style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 8, paddingVertical: 8 }}>
                {isLocating ? (
                  <ActivityIndicator size="small" color={colors.primaryDim} />
                ) : (
                  <>
                    <Ionicons name="navigate-circle-outline" size={24} color={colors.primaryDim} />
                    <Text style={{ fontFamily: 'Inter_600SemiBold', fontSize: 14, color: colors.primaryDim }}>Fetch Current Location</Text>
                  </>
                )}
              </Pressable>
            )}
          </View>

          <Button 
            title={mutation.isPending ? 'Saving...' : 'Save Changes'} 
            onPress={() => mutation.mutate()}
            disabled={mutation.isPending || !vendor}
          />

          {/* Danger Zone */}
          <View style={{ marginTop: 40, borderTopWidth: 1, borderTopColor: colors.surfaceMuted, paddingTop: 24 }}>
             <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 17, color: colors.error, marginBottom: 8 }}>Danger Zone</Text>
             <Text style={{ fontFamily: 'OpenSans_400Regular', fontSize: 13, color: colors.inkMuted, marginBottom: 16 }}>
               Deleting your store is permanent. All products, sales data, and store profile will be completely erased.
             </Text>
             <Pressable 
                onPress={handleDelete}
                disabled={deleteMutation.isPending}
                style={({ pressed }) => ({
                  backgroundColor: pressed ? colors.error : colors.errorGhost,
                  paddingVertical: 14,
                  borderRadius: 12,
                  alignItems: 'center',
                  borderWidth: 1,
                  borderColor: colors.error,
                  opacity: deleteMutation.isPending ? 0.7 : 1,
                })}
              >
                <Text style={{ fontFamily: 'Inter_700Bold', fontSize: 14, color: deleteMutation.isPending ? colors.surface : colors.error }}>
                  {deleteMutation.isPending ? 'Deleting...' : 'Delete Store'}
                </Text>
             </Pressable>
          </View>

        </ScrollView>
      )}
    </View>
  );
}

